screenPanels.initJs:
function(container, apiUrl, tables) {
  let currentProducts = [];
  let selectedOrders = [];

  // テーブルインデックス
  const STORES_TABLE = 1; // 店舗マスタ
  const PRODUCTS_TABLE = 2; // 商品マスタ
  const DEMAND_FORECAST_TABLE = 8; // 需要予測結果
  const ORDER_TABLE = 9; // 発注データ

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => errorDiv.classList.add('hidden'), 5000);
  }

  // 日付バリデーション
  function validateDateRange() {
    const startDate = container.querySelector('#date-start').value;
    const endDate = container.querySelector('#date-end').value;

    if (startDate && endDate && startDate > endDate) {
      showError('開始日は終了日より前の日付を入力してください');
      return false;
    }
    return true;
  }

  // 商品テーブル再描画
  function renderProducts(products) {
    const tbody = container.querySelector('#product-tbody');

    if (!products || products.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" class="muted">該当する商品が見つかりませんでした</td></tr>';
      return;
    }

    tbody.innerHTML = products.map(product => {
      const currentStock = Math.floor(Math.random() * 100) + 10; // 模擬在庫数
      const predictedDemand = Math.floor(Math.random() * 50) + 5; // 模擬予測需要
      const recommendedOrder = Math.max(0, predictedDemand - currentStock + 10); // 推奨発注量

      return `
        <tr data-id="${product.id}">
          <td><input type="checkbox" class="product-checkbox" data-product-id="${product.id}"></td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>${currentStock}</td>
          <td>${predictedDemand}</td>
          <td>${recommendedOrder}</td>
          <td>
            <div style="display: flex; align-items: center; gap: 5px;">
              <button class="adjust-btn" onclick="adjustQuantity('${product.id}', -1)">-</button>
              <input type="number" class="quantity-input" id="qty-${product.id}" 
                     value="${recommendedOrder}" min="0" max="999999999"
                     data-product-id="${product.id}">
              <button class="adjust-btn" onclick="adjustQuantity('${product.id}', 1)">+</button>
            </div>
          </td>
          <td>
            <input type="text" class="reason-input" id="reason-${product.id}" 
                   placeholder="発注理由" maxlength="500">
          </td>
          <td>
            <button class="action-btn secondary order-btn" data-product-id="${product.id}">発注</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 数量調整関数をグローバルに登録
  window.adjustQuantity = function(productId, delta) {
    const input = container.querySelector(`#qty-${productId}`);
    const currentValue = parseInt(input.value) || 0;
    const newValue = Math.max(0, Math.min(999999999, currentValue + delta));
    input.value = newValue;
  };

  // 店舗選択肢を読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(STORES_TABLE);
    const storeSelect = container.querySelector('#store-select');

    if (stores) {
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
        stores.filter(store => store.有効フラグ).map(store => 
          `<option value="${store.id}">${store.店舗名}</option>`
        ).join('');
    }
  }

  // 商品カテゴリ選択肢を読み込み（簡易実装）
  function loadCategories() {
    const categorySelect = container.querySelector('#category-select');
    categorySelect.innerHTML = `
      <option value="">全てのカテゴリ</option>
      <option value="食品">食品</option>
      <option value="日用品">日用品</option>
      <option value="衣料品">衣料品</option>
      <option value="家電">家電</option>
    `;
  }

  // 需要予測結果表示
  async function displayForecast(storeId) {
    const forecastDisplay = container.querySelector('#forecast-display');

    if (!storeId) {
      forecastDisplay.innerHTML = '<p class="muted">店舗を選択すると需要予測結果が表示されます</p>';
      return;
    }

    const forecasts = await window.aivicApi.list(DEMAND_FORECAST_TABLE);
    if (forecasts) {
      const storeForecast = forecasts.filter(f => f.店舗ID === storeId);
      if (storeForecast.length > 0) {
        const totalPredicted = storeForecast.reduce((sum, f) => sum + (f.予測数量 || 0), 0);
        const avgAccuracy = storeForecast.reduce((sum, f) => sum + (f.予測精度 || 0), 0) / storeForecast.length;

        forecastDisplay.innerHTML = `
          <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 15px;">
            <div>
              <div style="font-size: 24px; font-weight: bold; color: var(--primary);">${totalPredicted}</div>
              <div class="muted">総予測需要量</div>
            </div>
            <div>
              <div style="font-size: 24px; font-weight: bold; color: var(--primary);">${Math.round(avgAccuracy)}%</div>
              <div class="muted">平均予測精度</div>
            </div>
            <div>
              <div style="font-size: 24px; font-weight: bold; color: var(--primary);">${storeForecast.length}</div>
              <div class="muted">予測対象商品数</div>
            </div>
          </div>
        `;
      } else {
        forecastDisplay.innerHTML = '<p class="muted">この店舗の需要予測データがありません</p>';
      }
    }
  }

  // 商品検索・フィルタリング
  async function searchProducts() {
    if (!validateDateRange()) return;

    const storeId = container.querySelector('#store-select').value;
    const category = container.querySelector('#category-select').value;
    const searchTerm = container.querySelector('#product-search').value.toLowerCase();

    if (!storeId) {
      renderProducts([]);
      return;
    }

    const products = await window.aivicApi.list(PRODUCTS_TABLE);
    if (!products) return;

    let filteredProducts = products.filter(product => product.有効フラグ);

    // カテゴリフィルタ
    if (category) {
      filteredProducts = filteredProducts.filter(product => 
        product.商品名 && product.商品名.includes(category)
      );
    }

    // 検索フィルタ
    if (searchTerm) {
      filteredProducts = filteredProducts.filter(product => 
        (product.商品名 && product.商品名.toLowerCase().includes(searchTerm)) ||
        (product.商品コード && product.商品コード.toLowerCase().includes(searchTerm))
      );
    }

    currentProducts = filteredProducts;
    renderProducts(filteredProducts);
    displayForecast(storeId);
  }

  // 発注処理
  async function processOrder(productId, quantity, reason) {
    if (!quantity || quantity <= 0) {
      showError('発注量は正の数値を入力してください');
      return false;
    }

    if (isNaN(quantity)) {
      showError('発注量は数値で入力してください');
      return false;
    }

    const storeId = container.querySelector('#store-select').value;
    const product = currentProducts.find(p => p.id === productId);

    if (!product) {
      showError('商品情報が見つかりません');
      return false;
    }

    const orderData = {
      店舗ID: storeId,
      商品ID: productId,
      発注日: new Date().toISOString(),
      納期予定日: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(), // 7日後
      発注数量: parseInt(quantity),
      発注単価: product.単価 || 100,
      発注金額: parseInt(quantity) * (product.単価 || 100),
      発注方法: reason ? 'AI推奨修正' : 'AI推奨採用',
      発注ステータス: '発注済',
      仕入先ID: product.仕入先ID || 'default-supplier',
      発注理由: reason || 'AI推奨による自動発注',
      自動発注フラグ: !reason,
      作成者ID: 'current-user',
      更新者ID: 'current-user'
    };

    const result = await window.aivicApi.save(ORDER_TABLE, orderData);
    if (result) {
      return true;
    }
    return false;
  }

  // CSVエクスポート
  function exportCSV() {
    if (currentProducts.length === 0) {
      showError('エクスポートするデータがありません');
      return;
    }

    const headers = ['商品コード', '商品名', '現在在庫数', '予測需要量', '推奨発注量', '発注量', '発注理由'];
    const csvContent = '\uFEFF' + headers.join(',') + '\n' +
      currentProducts.map(product => {
        const qty = container.querySelector(`#qty-${product.id}`)?.value || '0';
        const reason = container.querySelector(`#reason-${product.id}`)?.value || '';
        const currentStock = Math.floor(Math.random() * 100) + 10;
        const predictedDemand = Math.floor(Math.random() * 50) + 5;
        const recommendedOrder = Math.max(0, predictedDemand - currentStock + 10);

        return [
          `"${product.商品コード || ''}"`,
          `"${product.商品名 || ''}"`,
          currentStock,
          predictedDemand,
          recommendedOrder,
          qty,
          `"${reason}"`
        ].join(',');
      }).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `order_management_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化
  loadStores();
  loadCategories();

  // 初期データ表示（空の状態）
  renderProducts([]);

  // イベントリスナー
  container.querySelector('#btn-search').addEventListener('click', searchProducts);

  container.querySelector('#store-select').addEventListener('change', (e) => {
    if (e.target.value) {
      searchProducts();
    } else {
      renderProducts([]);
      displayForecast(null);
    }
  });

  container.querySelector('#category-select').addEventListener('change', searchProducts);

  container.querySelector('#product-search').addEventListener('input', (e) => {
    if (e.target.value.length === 0 || e.target.value.length >= 2) {
      searchProducts();
    }
  });

  container.querySelector('#date-start').addEventListener('change', validateDateRange);
  container.querySelector('#date-end').addEventListener('change', validateDateRange);

  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // 発注ボタンのイベントデリゲーション
  container.addEventListener('click', async (e) => {
    const orderBtn = e.target.closest('.order-btn');
    if (orderBtn) {
      const productId = orderBtn.dataset.productId;
      const quantityInput = container.querySelector(`#qty-${productId}`);
      const reasonInput = container.querySelector(`#reason-${productId}`);

      const quantity = parseInt(quantityInput.value);
      const reason = reasonInput.value.trim();

      if (await processOrder(productId, quantity, reason)) {
        const product = currentProducts.find(p => p.id === productId);
        alert(`${product.商品名}の発注が完了しました。\n発注数量: ${quantity}\n発注理由: ${reason || 'AI推奨による自動発注'}`);

        // 発注後は入力をリセット
        quantityInput.value = '0';
        reasonInput.value = '';
      }
    }
  });

  // 数量入力のバリデーション
  container.addEventListener('input', (e) => {
    if (e.target.classList.contains('quantity-input')) {
      const value = e.target.value;
      if (value && (isNaN(value) || parseInt(value) < 0)) {
        e.target.style.borderColor = '#ff4444';
        showError('発注量は0以上の数値を入力してください');
      } else {
        e.target.style.borderColor = 'var(--border)';
      }
    }
  });
}

function(container, apiUrl, tables) {
  let currentPage = 1;
  let pageSize = 20;
  let filteredLogs = [];
  let allLogs = [];
  let autoUpdateInterval = null;

  // データ収集ログのテーブルインデックスを取得
  const logTableIndex = tables.findIndex(t => t.tableName === 'データ収集ログ');

  // ステータス表示用の関数
  function getStatusBadge(status) {
    const statusMap = {
      '成功': { class: 'status-success', text: '成功' },
      '失敗': { class: 'status-error', text: '失敗' },
      '警告': { class: 'status-warning', text: '警告' },
      '実行中': { class: 'status-running', text: '実行中' }
    };
    const statusInfo = statusMap[status] || { class: 'status-success', text: status };
    return `<span class="status-badge ${statusInfo.class}">${statusInfo.text}</span>`;
  }

  // 日時フォーマット関数
  function formatDateTime(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    });
  }

  // テーブル再描画関数
  function renderRows(logs) {
    const tbody = container.querySelector('#log-table-body');
    if (!logs || logs.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align: center; padding: 40px; color: var(--text-muted);">該当するログが見つかりません</td></tr>';
      return;
    }

    const startIndex = (currentPage - 1) * pageSize;
    const endIndex = startIndex + pageSize;
    const pageData = logs.slice(startIndex, endIndex);

    tbody.innerHTML = pageData.map(log => `
      <tr class="log-row" data-id="${log.ログID || log.id}" style="border-bottom: 1px solid var(--border);">
        <td style="padding: 12px 16px; color: var(--text);">${(log.ログID || log.id || '').substring(0, 8)}...</td>
        <td style="padding: 12px 16px; color: var(--text);">${log.データ種別 || ''}</td>
        <td style="padding: 12px 16px; color: var(--text);">${log.データソース || ''}</td>
        <td style="padding: 12px 16px; color: var(--text);">${formatDateTime(log.収集開始日時)}</td>
        <td style="padding: 12px 16px;">${getStatusBadge(log.処理ステータス || '成功')}</td>
        <td style="padding: 12px 16px; color: var(--text); text-align: right;">${log.収集件数 || 0}</td>
        <td style="padding: 12px 16px; color: var(--text); text-align: right;">${log.エラー件数 || 0}</td>
        <td style="padding: 12px 16px;">
          ${log.処理ステータス === '失敗' ? `<button class="action-btn secondary retry-btn" data-id="${log.ログID || log.id}" style="margin-right: 8px; padding: 4px 8px; font-size: 12px;">再実行</button>` : ''}
          <button class="action-btn secondary detail-btn" data-id="${log.ログID || log.id}" style="padding: 4px 8px; font-size: 12px;">詳細</button>
        </td>
      </tr>
    `).join('');

    updatePagination(logs.length);
  }

  // ページネーション更新
  function updatePagination(totalCount) {
    const totalPages = Math.ceil(totalCount / pageSize);
    const pageInfo = container.querySelector('#page-info');
    const prevBtn = container.querySelector('#btn-prev-page');
    const nextBtn = container.querySelector('#btn-next-page');

    pageInfo.textContent = `${currentPage} / ${totalPages}`;
    prevBtn.disabled = currentPage <= 1;
    nextBtn.disabled = currentPage >= totalPages;
  }

  // サマリー情報更新
  function updateSummary(logs) {
    const totalCount = logs.length;
    const successCount = logs.filter(log => log.処理ステータス === '成功').length;
    const errorCount = logs.filter(log => log.処理ステータス === '失敗').length;
    const successRate = totalCount > 0 ? Math.round((successCount / totalCount) * 100) : 0;

    container.querySelector('#total-count').textContent = totalCount.toLocaleString();
    container.querySelector('#success-rate').textContent = `${successRate}%`;
    container.querySelector('#error-count').textContent = errorCount.toLocaleString();

    // システム状態の更新
    const statusLight = container.querySelector('#status-light');
    const statusText = container.querySelector('#status-text');

    if (errorCount > totalCount * 0.1) { // エラー率10%以上
      statusLight.style.background = '#ef4444';
      statusText.textContent = 'エラー';
    } else if (errorCount > 0) {
      statusLight.style.background = '#f59e0b';
      statusText.textContent = '警告';
    } else {
      statusLight.style.background = '#22c55e';
      statusText.textContent = '正常';
    }
  }

  // フィルタリング関数
  function applyFilters() {
    const dataSource = container.querySelector('#filter-data-source').value;
    const logLevel = container.querySelector('#filter-log-level').value;
    const startDate = container.querySelector('#filter-start-date').value;
    const endDate = container.querySelector('#filter-end-date').value;

    // 日時バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert('終了日時は開始日時より後の日付を指定してください');
      return;
    }

    filteredLogs = allLogs.filter(log => {
      if (dataSource && log.データソース !== dataSource) return false;
      if (logLevel && !log.処理ステータス?.includes(logLevel)) return false;

      if (startDate) {
        const logDate = new Date(log.収集開始日時);
        if (logDate < new Date(startDate)) return false;
      }

      if (endDate) {
        const logDate = new Date(log.収集開始日時);
        if (logDate > new Date(endDate)) return false;
      }

      return true;
    });

    currentPage = 1;
    renderRows(filteredLogs);
    updateSummary(filteredLogs);
  }

  // CSVエクスポート関数
  function exportToCSV() {
    const headers = ['ログID', 'データ種別', 'データソース', '収集開始日時', '収集終了日時', '処理ステータス', '収集件数', 'エラー件数', 'エラーメッセージ'];
    const csvContent = [
      '\uFEFF' + headers.join(','),
      ...filteredLogs.map(log => [
        `"${log.ログID || log.id || ''}"`,
        `"${log.データ種別 || ''}"`,
        `"${log.データソース || ''}"`,
        `"${formatDateTime(log.収集開始日時)}"`,
        `"${formatDateTime(log.収集終了日時)}"`,
        `"${log.処理ステータス || ''}"`,
        log.収集件数 || 0,
        log.エラー件数 || 0,
        `"${(log.エラーメッセージ || '').replace(/"/g, '""')}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `data_collection_logs_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // ログ詳細表示
  function showLogDetail(logId) {
    const log = allLogs.find(l => (l.ログID || l.id) === logId);
    if (!log) return;

    const modal = container.querySelector('#log-detail-modal');
    const content = container.querySelector('#log-detail-content');

    content.innerHTML = `
      <div style="display: grid; gap: 16px;">
        <div><strong>ログID:</strong> ${log.ログID || log.id || ''}</div>
        <div><strong>データ種別:</strong> ${log.データ種別 || ''}</div>
        <div><strong>データソース:</strong> ${log.データソース || ''}</div>
        <div><strong>店舗ID:</strong> ${log.店舗ID || ''}</div>
        <div><strong>収集開始日時:</strong> ${formatDateTime(log.収集開始日時)}</div>
        <div><strong>収集終了日時:</strong> ${formatDateTime(log.収集終了日時)}</div>
        <div><strong>処理ステータス:</strong> ${getStatusBadge(log.処理ステータス || '成功')}</div>
        <div><strong>対象期間:</strong> ${formatDateTime(log.対象期間開始日)} ～ ${formatDateTime(log.対象期間終了日)}</div>
        <div><strong>収集件数:</strong> ${log.収集件数 || 0}件</div>
        <div><strong>エラー件数:</strong> ${log.エラー件数 || 0}件</div>
        <div><strong>処理時間:</strong> ${log.処理時間秒 || 0}秒</div>
        <div><strong>データ品質スコア:</strong> ${log.データ品質スコア || 0}/100</div>
        ${log.エラーメッセージ ? `<div><strong>エラーメッセージ:</strong><br><pre style="background: rgba(239, 68, 68, 0.1); padding: 12px; border-radius: 4px; white-space: pre-wrap; color: var(--text);">${log.エラーメッセージ}</pre></div>` : ''}
        ${log.備考 ? `<div><strong>備考:</strong> ${log.備考}</div>` : ''}
      </div>
    `;

    modal.style.display = 'block';
  }

  // 自動更新機能
  function toggleAutoUpdate() {
    const toggle = container.querySelector('#auto-update-toggle');
    if (toggle.checked) {
      autoUpdateInterval = setInterval(async () => {
        const logs = await window.aivicApi.list(logTableIndex);
        if (logs) {
          allLogs = logs;
          applyFilters();
        }
      }, 30000); // 30秒間隔
    } else {
      if (autoUpdateInterval) {
        clearInterval(autoUpdateInterval);
        autoUpdateInterval = null;
      }
    }
  }

  // 初期データ読み込み
  async function loadInitialData() {
    const logs = await window.aivicApi.list(logTableIndex);
    if (logs) {
      allLogs = logs;
      filteredLogs = logs;
      renderRows(filteredLogs);
      updateSummary(filteredLogs);
    } else {
      // APIが利用できない場合は初期データを使用
      allLogs = tables[logTableIndex]?.records || [];
      filteredLogs = allLogs;
      renderRows(filteredLogs);
      updateSummary(filteredLogs);
    }
  }

  // イベントリスナー設定

  // 検索ボタン
  container.querySelector('#btn-search').addEventListener('click', applyFilters);

  // フィルタクリア
  container.querySelector('#btn-clear-filters').addEventListener('click', () => {
    container.querySelector('#filter-data-source').value = '';
    container.querySelector('#filter-log-level').value = '';
    container.querySelector('#filter-start-date').value = '';
    container.querySelector('#filter-end-date').value = '';
    filteredLogs = allLogs;
    currentPage = 1;
    renderRows(filteredLogs);
    updateSummary(filteredLogs);
  });

  // エクスポートボタン
  container.querySelector('#btn-export').addEventListener('click', exportToCSV);

  // 自動更新トグル
  container.querySelector('#auto-update-toggle').addEventListener('change', toggleAutoUpdate);

  // アラート通知設定ボタン
  container.querySelector('#btn-alert-settings').addEventListener('click', () => {
    alert('アラート通知設定画面を表示します（実装予定）');
  });

  // ページネーション
  container.querySelector('#btn-prev-page').addEventListener('click', () => {
    if (currentPage > 1) {
      currentPage--;
      renderRows(filteredLogs);
    }
  });

  container.querySelector('#btn-next-page').addEventListener('click', () => {
    const totalPages = Math.ceil(filteredLogs.length / pageSize);
    if (currentPage < totalPages) {
      currentPage++;
      renderRows(filteredLogs);
    }
  });

  container.querySelector('#page-size').addEventListener('change', (e) => {
    pageSize = parseInt(e.target.value);
    currentPage = 1;
    renderRows(filteredLogs);
  });

  // モーダル関連
