    if (detailBtn) {
      const logId = detailBtn.dataset.id;
      showLogDetail(logId);
      return;
    }

    // 再実行ボタン
    const retryBtn = e.target.closest('.retry-btn');
    if (retryBtn) {
      if (!confirm('このログの処理を再実行しますか？')) return;

      const logId = retryBtn.dataset.id;
      // 実際の再実行処理はここで実装
      alert('再実行処理を開始しました');

      // ログを再読み込み
      setTimeout(async () => {
        const logs = await window.aivicApi.list(logTableIndex);
        if (logs) {
          allLogs = logs;
          applyFilters();
        }
      }, 1000);
      return;
    }
  });

  // モーダル外クリックで閉じる
  container.querySelector('#log-detail-modal').addEventListener('click', (e) => {
    if (e.target === container.querySelector('#log-detail-modal')) {
      container.querySelector('#log-detail-modal').style.display = 'none';
