  });

  // 初期データ読み込み実行
  loadInitialData();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#history-tbody");
  const pageSize = 20;
  let currentPage = 1;
  let totalPages = 1;
  let allHistories = [];
  let filteredHistories = [];

  // ユーザー一覧を取得してセレクトボックスに設定
  async function loadUsers() {
    const users = await window.aivicApi.list(0); // ログインユーザーテーブル
    const userSelect = container.querySelector("#user-filter");
    if (users) {
      users.forEach(user => {
        const option = document.createElement("option");
        option.value = user.ユーザーID;
        option.textContent = user.ユーザー名;
        userSelect.appendChild(option);
      });
    }
  }

  // 操作履歴一覧の再描画
  function renderHistories(histories) {
    const startIndex = (currentPage - 1) * pageSize;
    const endIndex = startIndex + pageSize;
    const pageHistories = histories.slice(startIndex, endIndex);

    tbody.innerHTML = pageHistories.map(history => `
      <tr data-id="${history.操作履歴ID}">
        <td>${formatDateTime(history.操作日時)}</td>
        <td>${getUserName(history.ユーザーID)}</td>
        <td>${history.操作種別 || ""}</td>
        <td>${history.操作画面 || ""}</td>
        <td>${history.IPアドレス || ""}</td>
        <td><span class="status-badge ${getResultClass(history.処理結果)}">${history.処理結果 || ""}</span></td>
        <td>${history.処理時間 ? history.処理時間 + "ms" : ""}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${history.操作履歴ID}">詳細</button>
        </td>
      </tr>
    `).join("");

    updatePagination(histories.length);
  }

  // 日時フォーマット
  function formatDateTime(dateTime) {
    if (!dateTime) return "";
    const date = new Date(dateTime);
    return date.toLocaleString("ja-JP");
  }

  // ユーザー名取得
  function getUserName(userId) {
    if (!userId || !tables[0]) return "";
    const user = tables[0].records.find(u => u.ユーザーID === userId);
    return user ? user.ユーザー名 : "";
  }

  // 処理結果のクラス取得
  function getResultClass(result) {
    switch(result) {
      case "成功": return "success";
      case "失敗": return "error";
      case "エラー": return "error";
      default: return "";
    }
  }

  // ページネーション更新
  function updatePagination(totalCount) {
    totalPages = Math.ceil(totalCount / pageSize);
    container.querySelector("#page-info").textContent = `${currentPage} / ${totalPages}`;
    container.querySelector("#btn-prev").disabled = currentPage <= 1;
    container.querySelector("#btn-next").disabled = currentPage >= totalPages;
  }

  // 検索フィルター適用
  function applyFilters() {
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const userId = container.querySelector("#user-filter").value;
    const operationType = container.querySelector("#operation-type-filter").value;
    const screenName = container.querySelector("#screen-search").value.toLowerCase();
    const ipAddress = container.querySelector("#ip-search").value;
    const result = container.querySelector("#result-filter").value;

    // 日付範囲バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      showError("開始日は終了日より前の日付を入力してください");
      return;
    }

    // IPアドレスバリデーション
    if (ipAddress && !isValidIpAddress(ipAddress)) {
      showError("正しいIPアドレス形式で入力してください");
      return;
    }

    filteredHistories = allHistories.filter(history => {
      // 日付範囲フィルター
      if (startDate && new Date(history.操作日時) < new Date(startDate)) return false;
      if (endDate && new Date(history.操作日時) > new Date(endDate + " 23:59:59")) return false;

      // ユーザーフィルター
      if (userId && history.ユーザーID !== userId) return false;

      // 操作種別フィルター
      if (operationType && history.操作種別 !== operationType) return false;

      // 画面名・機能名検索
      if (screenName && !history.操作画面?.toLowerCase().includes(screenName)) return false;

      // IPアドレス検索
      if (ipAddress && history.IPアドレス !== ipAddress) return false;

      // 処理結果フィルター
      if (result && history.処理結果 !== result) return false;

      return true;
    });

    currentPage = 1;
    renderHistories(filteredHistories);

    if (filteredHistories.length === 0) {
      showError("該当する操作履歴が見つかりませんでした");
    }
  }

  // IPアドレスバリデーション
  function isValidIpAddress(ip) {
    // IPv4の基本的なバリデーション
    const ipv4Regex = /^(\d{1,3}\.){3}\d{1,3}$/;
    // IPv6の基本的なバリデーション
    const ipv6Regex = /^([0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$|^::1$|^::$/;

    if (ipv4Regex.test(ip)) {
      const parts = ip.split('.');
      return parts.every(part => parseInt(part) >= 0 && parseInt(part) <= 255);
    }

    return ipv6Regex.test(ip);
  }

  // エラーメッセージ表示
  function showError(message) {
    const existingError = container.querySelector(".error-message");
    if (existingError) existingError.remove();

    const errorDiv = document.createElement("div");
    errorDiv.className = "error-message";
    errorDiv.textContent = message;
    container.querySelector(".search-section").appendChild(errorDiv);

    setTimeout(() => errorDiv.remove(), 5000);
  }

  // 成功メッセージ表示
  function showSuccess(message) {
    const existingSuccess = container.querySelector(".success-message");
    if (existingSuccess) existingSuccess.remove();

    const successDiv = document.createElement("div");
    successDiv.className = "success-message";
    successDiv.textContent = message;
    container.querySelector(".search-section").appendChild(successDiv);

    setTimeout(() => successDiv.remove(), 3000);
  }

  // CSV出力
  function exportToCsv() {
    if (filteredHistories.length === 0) {
      showError("出力可能なデータがありません");
      return;
    }

    const headers = ["操作日時", "ユーザー名", "操作種別", "操作画面", "操作対象テーブル", "操作対象ID", "操作内容", "IPアドレス", "ユーザーエージェント", "処理結果", "エラーメッセージ", "処理時間"];

    const csvContent = [
      headers.join(","),
      ...filteredHistories.map(history => [
        `"${formatDateTime(history.操作日時)}"`,
        `"${getUserName(history.ユーザーID)}"`,
        `"${history.操作種別 || ""}"`,
        `"${history.操作画面 || ""}"`,
        `"${history.操作対象テーブル || ""}"`,
        `"${history.操作対象ID || ""}"`,
        `"${(history.操作内容 || "").replace(/"/g, '""')}"`,
        `"${history.IPアドレス || ""}"`,
        `"${(history.ユーザーエージェント || "").replace(/"/g, '""')}"`,
        `"${history.処理結果 || ""}"`,
        `"${(history.エラーメッセージ || "").replace(/"/g, '""')}"`,
        `"${history.処理時間 || ""}"`
      ].join(","))
    ].join("\n");

    const bom = "\uFEFF";
    const blob = new Blob([bom + csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `操作履歴_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();

    showSuccess("CSVファイルをダウンロードしました");
  }

  // 詳細モーダル表示
  function showDetailModal(historyId) {
    const history = allHistories.find(h => h.操作履歴ID === historyId);
    if (!history) return;

    container.querySelector("#detail-datetime").textContent = formatDateTime(history.操作日時);
    container.querySelector("#detail-user").textContent = getUserName(history.ユーザーID);
    container.querySelector("#detail-operation").textContent = history.操作種別 || "";
    container.querySelector("#detail-screen").textContent = history.操作画面 || "";
    container.querySelector("#detail-table").textContent = history.操作対象テーブル || "";
    container.querySelector("#detail-target-id").textContent = history.操作対象ID || "";
    container.querySelector("#detail-content").textContent = history.操作内容 || "";
    container.querySelector("#detail-ip").textContent = history.IPアドレス || "";
    container.querySelector("#detail-user-agent").textContent = history.ユーザーエージェント || "";
    container.querySelector("#detail-result").textContent = history.処理結果 || "";
    container.querySelector("#detail-time").textContent = history.処理時間 ? history.処理時間 + "ms" : "";
    container.querySelector("#detail-error").textContent = history.エラーメッセージ || "";

    container.querySelector("#detail-modal").classList.remove("hidden");
  }

  // 初期データ読み込み
  async function loadData() {
    const histories = await window.aivicApi.list(12); // システム操作履歴テーブル
    if (histories) {
      allHistories = histories;
      filteredHistories = histories;
      renderHistories(filteredHistories);
    } else {
      allHistories = tables[12]?.records || [];
      filteredHistories = allHistories;
      renderHistories(filteredHistories);
    }
  }

  // イベントリスナー設定
  container.querySelector("#btn-search").addEventListener("click", applyFilters);

  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#start-date").value = "";
    container.querySelector("#end-date").value = "";
    container.querySelector("#user-filter").value = "";
    container.querySelector("#operation-type-filter").value = "";
    container.querySelector("#screen-search").value = "";
    container.querySelector("#ip-search").value = "";
    container.querySelector("#result-filter").value = "";

    filteredHistories = allHistories;
    currentPage = 1;
    renderHistories(filteredHistories);
  });

  container.querySelector("#btn-csv-export").addEventListener("click", exportToCsv);

  container.querySelector("#btn-prev").addEventListener("click", () => {
    if (currentPage > 1) {
      currentPage--;
      renderHistories(filteredHistories);
    }
  });

  container.querySelector("#btn-next").addEventListener("click", () => {
    if (currentPage < totalPages) {
      currentPage++;
      renderHistories(filteredHistories);
    }
  });

  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    container.querySelector("#detail-modal").classList.add("hidden");
  });

  container.querySelector("#detail-modal").addEventListener("click", (e) => {
    if (e.target.id === "detail-modal") {
      container.querySelector("#detail-modal").classList.add("hidden");
    }
  });

  // イベントデリゲーション
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      showDetailModal(detailBtn.dataset.id);
    }
  });

  // 初期化
  loadUsers();
  loadData();

  // スタイル追加
  const style = document.createElement("style");
  style.textContent = `
    .status-badge {
      padding: 4px 8px;
      border-radius: 4px;
      font-size: 12px;
      font-weight: 500;
    }
    .status-badge.success {
      background: rgba(81, 207, 102, 0.1);
      color: #51cf66;
      border: 1px solid #51cf66;
    }
    .status-badge.error {
      background: rgba(255, 107, 107, 0.1);
      color: #ff6b6b;
      border: 1px solid #ff6b6b;
    }
  `;
  document.head.appendChild(style);
}

function(container, apiUrl, tables) {
  // 初期化処理
  const today = new Date().toISOString().split('T')[0];
  const oneYearAgo = new Date();
  oneYearAgo.setFullYear(oneYearAgo.getFullYear() - 1);
  const oneYearAgoStr = oneYearAgo.toISOString().split('T')[0];

  // デフォルト値設定
  container.querySelector('#learning-start-date').value = oneYearAgoStr;
  container.querySelector('#learning-end-date').value = today;

  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  const tomorrowStr = tomorrow.toISOString().split('T')[0];
  container.querySelector('#prediction-start-date').value = tomorrowStr;

  const nextWeek = new Date();
  nextWeek.setDate(nextWeek.getDate() + 7);
  const nextWeekStr = nextWeek.toISOString().split('T')[0];
  container.querySelector('#prediction-end-date').value = nextWeekStr;

  // 店舗データの読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(1); // 店舗マスタ
    const storeSelect = container.querySelector('#store-select');
    if (stores) {
      stores.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 商品カテゴリの読み込み
  async function loadProductCategories() {
    const products = await window.aivicApi.list(2); // 商品マスタ
    const categoryContainer = container.querySelector('#category-checkboxes');
    if (products) {
      const categories = [...new Set(products.map(p => p.商品カテゴリID).filter(Boolean))];
      categories.forEach(categoryId => {
        const label = document.createElement('label');
        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.value = categoryId;
        checkbox.name = 'product-categories';
        label.appendChild(checkbox);
        label.appendChild(document.createTextNode(`カテゴリ ${categoryId.substring(0, 8)}`));
        categoryContainer.appendChild(label);
      });
    }
  }

  // スライダーの値更新
  function setupSliders() {
    const sliders = ['spring', 'summer', 'autumn', 'winter'];
    sliders.forEach(season => {
      const slider = container.querySelector(`#${season}-factor`);
      const valueSpan = container.querySelector(`#${season}-value`);
      slider.addEventListener('input', () => {
        valueSpan.textContent = slider.value;
      });
    });
  }

  // バリデーション関数
  function validateForm() {
    const errors = [];

    // 予測対象期間チェック
    const startDate = new Date(container.querySelector('#prediction-start-date').value);
    const endDate = new Date(container.querySelector('#prediction-end-date').value);
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    if (startDate <= today) {
      errors.push('予測対象期間に過去の日付は選択できません');
    }

    if (endDate <= startDate) {
      errors.push('予測対象期間の終了日は開始日より後の日付を選択してください');
    }

    // 店舗選択チェック
    if (!container.querySelector('#store-select').value) {
      errors.push('店舗を選択してください');
    }

    // 商品カテゴリ選択チェック
    const selectedCategories = container.querySelectorAll('input[name="product-categories"]:checked');
    if (selectedCategories.length === 0) {
      errors.push('商品カテゴリを選択してください');
    }

    // 予測モデル選択チェック
    const selectedModel = container.querySelector('input[name="prediction-model"]:checked');
    if (!selectedModel) {
      errors.push('予測モデルを選択してください');
    }

    // 学習データ期間チェック
    const learningStart = container.querySelector('#learning-start-date').value;
    const learningEnd = container.querySelector('#learning-end-date').value;
    if (!learningStart || !learningEnd) {
      errors.push('学習データ期間を設定してください');
    }

    // 予測精度閾値チェック
    const threshold = parseInt(container.querySelector('#accuracy-threshold').value);
    if (isNaN(threshold) || threshold < 0 || threshold > 100) {
      errors.push('予測精度閾値は0-100の範囲で入力してください');
    }

    return errors;
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // 進捗バー更新
  function updateProgress(percentage, message) {
    const progressFill = container.querySelector('#progress-fill');
    const progressText = container.querySelector('#progress-text');
    progressFill.style.width = `${percentage}%`;
    progressText.textContent = `${message} ${percentage}%`;
  }

  // 天候データ取込
  async function importWeatherData() {
    const statusSpan = container.querySelector('#weather-status');
    statusSpan.textContent = '取込中...';
    statusSpan.className = 'status-indicator loading';

    try {
      // 模擬的な天候データ取込処理
      await new Promise(resolve => setTimeout(resolve, 2000));

      // 成功時の処理
      statusSpan.textContent = '取込完了';
      statusSpan.className = 'status-indicator success';
    } catch (error) {
      statusSpan.textContent = '取込失敗';
      statusSpan.className = 'status-indicator error';
      showError('天候データの取込に失敗しました。ネットワーク接続を確認してください。');
    }
  }

  // イベントデータ取込
  async function importEventData() {
    const statusSpan = container.querySelector('#event-status');
    statusSpan.textContent = '取込中...';
    statusSpan.className = 'status-indicator loading';

    try {
      // 模擬的なイベントデータ取込処理
      await new Promise(resolve => setTimeout(resolve, 1500));

      // 成功時の処理
      statusSpan.textContent = '取込完了';
      statusSpan.className = 'status-indicator success';
    } catch (error) {
      statusSpan.textContent = '取込失敗';
      statusSpan.className = 'status-indicator error';
      showError('イベントデータの取込に失敗しました。ファイル形式または必須項目を確認してください。');
    }
  }

  // AI予測実行
  async function executePrediction() {
    const errors = validateForm();
    if (errors.length > 0) {
      showError(errors.join('\n'));
      return;
    }

    const executeBtn = container.querySelector('#btn-execute-prediction');
    const progressContainer = container.querySelector('#progress-container');

    executeBtn.disabled = true;
    executeBtn.textContent = '実行中...';
    progressContainer.classList.remove('hidden');

    try {
      // 予測処理のシミュレーション
      const steps = [
        { percentage: 10, message: 'データ準備中...' },
        { percentage: 30, message: 'モデル学習中...' },
        { percentage: 60, message: '予測計算中...' },
        { percentage: 80, message: '結果検証中...' },
        { percentage: 100, message: '処理完了' }
      ];

      for (const step of steps) {
        updateProgress(step.percentage, step.message);
        await new Promise(resolve => setTimeout(resolve, 1000));
      }

      // 予測結果データの保存
      const predictionData = {
        店舗ID: container.querySelector('#store-select').value,
        商品ID: 'dummy-product-id',
        予測対象日: container.querySelector('#prediction-start-date').value,
        予測数量: Math.floor(Math.random() * 100) + 50,
        予測精度: Math.floor(Math.random() * 20) + 80,
        推奨発注数量: Math.floor(Math.random() * 80) + 40,
        予測モデルバージョン: container.querySelector('input[name="prediction-model"]:checked').value,
        予測ステータス: '完了',
        発注済フラグ: false,
        備考: 'AI自動予測結果',
        作成日時: new Date().toISOString(),
        更新日時: new Date().toISOString()
      };

      const saved = await window.aivicApi.save(9, predictionData); // 需要予測結果テーブル

      if (saved) {
        // 需要予測管理画面に遷移
        window.showScreen('scr-1778591838939');
      } else {
        showError('予測結果の保存に失敗しました');
      }

    } catch (error) {
      showError('AI予測処理中にエラーが発生しました');
    } finally {
      executeBtn.disabled = false;
      executeBtn.textContent = 'AI予測実行';
      progressContainer.classList.add('hidden');
    }
  }

  // イベントリスナーの設定
  container.querySelector('#btn-import-weather').addEventListener('click', importWeatherData);
  container.querySelector('#btn-import-event').addEventListener('click', importEventData);
  container.querySelector('#btn-execute-prediction').addEventListener('click', executePrediction);

  // 初期化実行
  loadStores();
  loadProductCategories();
  setupSliders();
}

function(container, apiUrl, tables) {
