  let currentForecast = {};

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => errorDiv.classList.add('hidden'), 5000);
  }

  // バリデーション関数
  function validateInputs() {
    const storeId = container.querySelector('#select-store').value;
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return false;
    }

    if (!startDate || !endDate) {
      showError('対象期間を設定してください');
      return false;
    }

    const start = new Date(startDate);
    const end = new Date(endDate);
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    if (start > today && end > today) {
      showError('対象期間に過去または現在の日付を含めてください');
      return false;
    }

    if (start > end) {
      showError('開始日は終了日より前の日付を選択してください');
      return false;
    }

    return true;
  }

  // 数値バリデーション関数
  function validateNumber(value, fieldName, min = 0, max = null) {
    if (value === '' || value === null || value === undefined) return true;

    const num = parseFloat(value);
    if (isNaN(num)) {
      showError(`${fieldName}は数値を入力してください`);
      return false;
    }

    if (num < min) {
      showError(`${fieldName}は${min}以上の値を入力してください`);
      return false;
    }

    if (max !== null && num > max) {
      showError(`${fieldName}は${max}以下の値を入力してください`);
      return false;
    }

    return true;
  }

  // 店舗データ読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(1); // 店舗マスタ
    if (!stores) return;

    const select = container.querySelector('#select-store');
    select.innerHTML = '<option value="">店舗を選択してください</option>';

    stores.filter(store => store.有効フラグ).forEach(store => {
      const option = document.createElement('option');
      option.value = store.店舗ID;
      option.textContent = `${store.店舗コード} - ${store.店舗名}`;
      select.appendChild(option);
    });
  }

  // 商品検索・絞り込み
  async function searchProducts() {
    const keyword = container.querySelector('#input-search').value.trim();
    const category = container.querySelector('#select-category').value;

    const products = await window.aivicApi.list(2); // 商品マスタ
    if (!products) return;

    let filtered = products.filter(product => product.有効フラグ && product.AI予測対象フラグ);

    if (keyword) {
      filtered = filtered.filter(product => 
        product.商品名.includes(keyword) || product.商品コード.includes(keyword)
      );
    }

    if (category) {
      // カテゴリでの絞り込み（簡易実装）
      filtered = filtered.filter(product => 
        product.商品名.includes(category)
      );
    }

    currentProducts = filtered;
    renderCalculationTable();
  }

  // 需要予測更新
  async function updateForecast() {
    if (!validateInputs()) return;

    const storeId = container.querySelector('#select-store').value;
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;

    const forecastDisplay = container.querySelector('#forecast-display');
    forecastDisplay.innerHTML = '<div style="color: var(--text);">予測計算中...</div>';

    try {
      // 需要予測結果を取得
      const forecasts = await window.aivicApi.list(8); // 需要予測結果
      if (!forecasts) {
        forecastDisplay.innerHTML = '<div style="color: var(--text-muted);">予測データの取得に失敗しました</div>';
        return;
      }

      // 指定期間・店舗の予測データをフィルタ
      const filtered = forecasts.filter(f => 
        f.店舗ID === storeId &&
        f.予測対象日 >= startDate &&
        f.予測対象日<= endDate
      );

      currentForecast = {};
      filtered.forEach(f => {
        currentForecast[f.商品ID] = f;
      });

      const totalProducts = Object.keys(currentForecast).length;
      const avgAccuracy = filtered.length > 0 
        ? Math.round(filtered.reduce((sum, f) => sum + (f.予測精度 || 85), 0) / filtered.length)
        : 85;

      forecastDisplay.innerHTML = `
        <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 20px; text-align: center;">
          <div>
            <div style="font-size: 24px; font-weight: 600; color: var(--primary);">${totalProducts}</div>
            <div style="color: var(--text-muted);">予測対象商品数</div>
          </div>
          <div>
            <div style="font-size: 24px; font-weight: 600; color: var(--primary);">${avgAccuracy}%</div>
            <div style="color: var(--text-muted);">平均予測精度</div>
          </div>
          <div>
            <div style="font-size: 24px; font-weight: 600; color: var(--primary);">${startDate} ～ ${endDate}</div>
            <div style="color: var(--text-muted);">予測期間</div>
          </div>
        </div>
      `;

    } catch (error) {
      forecastDisplay.innerHTML = '<div style="color: var(--text-muted);">予測データの更新に失敗しました</div>';
    }
  }

  // 発注量計算テーブル描画
  function renderCalculationTable() {
    const tbody = container.querySelector('#calculation-tbody');

    if (currentProducts.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="9" style="text-align: center; color: var(--text-muted); padding: 40px;">
            商品を検索して発注量を計算してください
          </td>
        </tr>
      `;
      return;
    }

    tbody.innerHTML = currentProducts.map(product => {
      const forecast = currentForecast[product.商品ID];
      const recommendedQty = forecast ? forecast.推奨発注数量 || 0 : 0;

      return `
        <tr data-product-id="${product.商品ID}">
          <td style="color: var(--text);">${product.商品名}</td>
          <td>
            <input type="number" class="input current-stock" 
                   style="width: 80px;" min="0" value="0" 
                   data-product-id="${product.商品ID}">
          </td>
          <td>
            <input type="number" class="input safety-stock" 
                   style="width: 80px;" min="0" value="${product.最小発注数量 || 10}" 
                   data-product-id="${product.商品ID}">
          </td>
          <td>
            <input type="number" class="input lead-time" 
                   style="width: 80px;" min="1" max="365" value="${product.リードタイム日数 || 7}" 
                   data-product-id="${product.商品ID}">
          </td>
          <td>
            <input type="number" class="input weather-impact" 
                   style="width: 80px;" min="0" max="100" value="100" 
                   data-product-id="${product.商品ID}">
          </td>
          <td>
            <input type="number" class="input season-factor" 
                   style="width: 80px;" min="0" step="0.1" value="1.0" 
                   data-product-id="${product.商品ID}">
          </td>
          <td style="color: var(--text); font-weight: 600;">${recommendedQty}</td>
          <td>
            <input type="number" class="input manual-adjust" 
                   style="width: 80px;" min="0" value="${recommendedQty}" 
                   data-product-id="${product.商品ID}">
          </td>
          <td class="final-quantity" style="color: var(--primary); font-weight: 600;" 
              data-product-id="${product.商品ID}">${recommendedQty}</td>
        </tr>
      `;
    }).join('');

    // 入力値変更時の再計算
    tbody.addEventListener('input', handleInputChange);
  }

  // 入力値変更時の処理
  function handleInputChange(e) {
    const input = e.target;
    const productId = input.dataset.productId;

    if (!productId) return;

    // バリデーション
    const value = input.value;
    const fieldName = getFieldName(input.className);

    if (input.classList.contains('current-stock') && !validateNumber(value, '現在在庫数', 0)) {
      input.focus();
      return;
    }

    if (input.classList.contains('safety-stock') && !validateNumber(value, '安全在庫', 0)) {
      input.focus();
      return;
    }

    if (input.classList.contains('lead-time') && !validateNumber(value, 'リードタイム', 1, 365)) {
      input.focus();
      return;
    }

    if (input.classList.contains('weather-impact') && !validateNumber(value, '天候影響度', 0, 100)) {
      input.focus();
      return;
    }

    if (input.classList.contains('season-factor') && !validateNumber(value, '季節補正係数', 0)) {
      input.focus();
      return;
    }

    if (input.classList.contains('manual-adjust') && !validateNumber(value, '手動調整', 0)) {
      input.focus();
      return;
    }

    // 発注量再計算
    calculateOrderQuantity(productId);
  }

  function getFieldName(className) {
    if (className.includes('current-stock')) return '現在在庫数';
    if (className.includes('safety-stock')) return '安全在庫';
    if (className.includes('lead-time')) return 'リードタイム';
    if (className.includes('weather-impact')) return '天候影響度';
    if (className.includes('season-factor')) return '季節補正係数';
    if (className.includes('manual-adjust')) return '手動調整';
    return 'フィールド';
  }

  // 発注量計算
  function calculateOrderQuantity(productId) {
    const row = container.querySelector(`tr[data-product-id="${productId}"]`);
    if (!row) return;

    const currentStock = parseFloat(row.querySelector('.current-stock').value) || 0;
    const safetyStock = parseFloat(row.querySelector('.safety-stock').value) || 0;
    const leadTime = parseFloat(row.querySelector('.lead-time').value) || 7;
    const weatherImpact = parseFloat(row.querySelector('.weather-impact').value) || 100;
    const seasonFactor = parseFloat(row.querySelector('.season-factor').value) || 1.0;
    const manualAdjust = parseFloat(row.querySelector('.manual-adjust').value) || 0;

    // AI推奨発注量を取得
    const forecast = currentForecast[productId];
    let baseQuantity = forecast ? forecast.推奨発注数量 || 0 : 0;

    // 各種補正を適用
    baseQuantity = baseQuantity * (weatherImpact / 100) * seasonFactor;

    // リードタイム期間の需要を考慮
    const leadTimeDemand = baseQuantity * (leadTime / 7); // 週単位で計算

    // 最終発注量 = 予測需要 + 安全在庫 - 現在在庫 + リードタイム需要
    let finalQuantity = Math.max(0, leadTimeDemand + safetyStock - currentStock);

    // 手動調整が入力されている場合はそれを優先
    if (manualAdjust > 0) {
      finalQuantity = manualAdjust;
    }

    // 結果を表示
    const finalCell = row.querySelector('.final-quantity');
    finalCell.textContent = Math.round(finalQuantity);
  }

  // 全商品の発注量計算
  function calculateAllOrderQuantities() {
    if (currentProducts.length === 0) {
      showError('商品が選択されていません');
      return;
    }

    currentProducts.forEach(product => {
      calculateOrderQuantity(product.商品ID);
    });
  }

  // イベントリスナー設定
  container.querySelector('#btn-dashboard').addEventListener('click', () => {
    window.showScreen('scr-1778591780173');
  });

  container.querySelector('#btn-order-management').addEventListener('click', () => {
    window.showScreen('scr-1778591852463');
  });

  container.querySelector('#btn-search').addEventListener('click', searchProducts);

  container.querySelector('#btn-filter').addEventListener('click', searchProducts);

  container.querySelector('#btn-forecast-update').addEventListener('click', updateForecast);

  container.querySelector('#btn-calculate').addEventListener('click', calculateAllOrderQuantities);

  // 初期化
  loadStores();

  // 今日の日付を初期値として設定
  const today = new Date();
  const todayStr = today.toISOString().split('T')[0];
  const weekAgo = new Date(today.getTime() - 7 * 24 * 60 * 60 * 1000);
  const weekAgoStr = weekAgo.toISOString().split('T')[0];

  container.querySelector('#input-start-date').value = weekAgoStr;
  container.querySelector('#input-end-date').value = todayStr;
}

