    if (predictionData) {
      demandPredictions = predictionData;
    } else {
      demandPredictions = tables.find(t => t.tableName === '需要予測結果')?.records || [];
    }

    renderProducts();
  }

  // イベントリスナー設定
  container.querySelector('#category-select').addEventListener('change', (e) => {
    const categoryId = e.target.value;
    const filteredProducts = categoryId ? 
      allProducts.filter(p => p.商品カテゴリID === categoryId) : 
      allProducts;
    renderProducts(filteredProducts);
  });

  container.querySelector('#btn-product-search').addEventListener('click', () => {
    const keyword = container.querySelector('#product-search').value.toLowerCase();
    const filteredProducts = keyword ? 
      allProducts.filter(p => 
        (p.商品名 || '').toLowerCase().includes(keyword) || 
        (p.商品コード || '').toLowerCase().includes(keyword)
      ) : allProducts;
    renderProducts(filteredProducts);
  });

  container.querySelector('#product-search').addEventListener('keypress', (e) => {
    if (e.key === 'Enter') {
      container.querySelector('#btn-product-search').click();
    }
  });

  // 手動調整数量のバリデーション
  container.addEventListener('input', (e) => {
    if (e.target.classList.contains('manual-qty')) {
      const value = parseInt(e.target.value);
      if (value < 0) {
        alert('手動調整数量は0以上の値を入力してください');
        e.target.value = '';
      }
    }
  });

  // イベントデリゲーション
  container.addEventListener('click', (e) => {
    const addBtn = e.target.closest('.add-to-order-btn');
    if (addBtn) {
      addToOrder(addBtn.dataset.productId);
      return;
    }

    const removeBtn = e.target.closest('.remove-from-order-btn');
    if (removeBtn) {
      removeFromOrder(removeBtn.dataset.productId);
      return;
    }

    const reasonBtn = e.target.closest('.prediction-reason-btn');
    if (reasonBtn) {
      showPredictionReason(reasonBtn.dataset.productId);
      return;
    }
  });

  // モーダル関連
  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#prediction-modal').classList.add('hidden');
  });

  container.querySelector('#btn-stock-check').addEventListener('click', showStockStatus);
  container.querySelector('#btn-close-stock-modal').addEventListener('click', () => {
    container.querySelector('#stock-modal').classList.add('hidden');
  });

  container.querySelector('#btn-past-data').addEventListener('click', showPastData);
  container.querySelector('#btn-close-past-modal').addEventListener('click', () => {
    container.querySelector('#past-data-modal').classList.add('hidden');
  });

  container.querySelector('#btn-get-past-data').addEventListener('click', getPastData);

  // メインボタン
  container.querySelector('#btn-create-order').addEventListener('click', createOrder);
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    window.showScreen('scr-1778591852463'); // 発注管理画面に戻る
  });

  // 初期化
  loadStores();
  loadCategories();
  loadInitialData();
}

function(container, apiUrl, tables) {
  // 現在の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#order-date').value = today;

  let currentStoreId = '';
  let orderData = [];
  let selectedOrderIds = new Set();

  // 店舗マスタのテーブルインデックス（1番目）
  const storeTableIndex = 1;
  // 発注データのテーブルインデックス（7番目）
  const orderTableIndex = 7;
  // 商品マスタのテーブルインデックス（2番目）
  const productTableIndex = 2;
  // 需要予測結果のテーブルインデックス（6番目）
  const forecastTableIndex = 6;

  // 店舗選択肢を初期化
  async function initStoreOptions() {
    try {
      const stores = await window.aivicApi.list(storeTableIndex);
      const storeSelect = container.querySelector('#store-select');
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';

      if (stores) {
        stores.filter(store => store.有効フラグ).forEach(store => {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        });
      }
    } catch (error) {
      showError('店舗データの取得に失敗しました');
    }
  }

  // 発注データ一覧を描画
  function renderOrderList(orders) {
    const tbody = container.querySelector('#order-list-tbody');

    if (!orders || orders.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="8" class="muted" style="text-align: center; padding: 2rem;">
            発注データがありません
          </td>
        </tr>
      `;
      updateSendButton();
      return;
    }

    tbody.innerHTML = orders.map(order => `
      <tr data-id="${order.発注ID}">
        <td>
          <input type="checkbox" class="order-checkbox" data-id="${order.発注ID}" 
                 ${selectedOrderIds.has(order.発注ID) ? 'checked' : ''}>
        </td>
        <td>${order.商品コード || ''}</td>
        <td>${order.商品名 || ''}</td>
        <td>${order.予測数量 || 0}</td>
        <td>${order.発注数量 || 0}</td>
        <td>${order.仕入先名 || ''}</td>
        <td>¥${(order.発注金額 || 0).toLocaleString()}</td>
        <td>
          <span class="status-badge ${getStatusClass(order.発注ステータス)}">
            ${order.発注ステータス || '未送信'}
          </span>
        </td>
      </tr>
    `).join('');

    updateSelectAllCheckbox();
    updateSendButton();
  }

  // ステータスに応じたCSSクラスを取得
  function getStatusClass(status) {
    switch (status) {
      case '送信済み': return 'status-sent';
      case '送信中': return 'status-sending';
      case 'エラー': return 'status-error';
      default: return 'status-pending';
    }
  }

  // 店舗選択時の処理
  async function loadOrderData(storeId) {
    if (!storeId) {
      renderOrderList([]);
      return;
    }

    try {
      // 発注データを取得
      const orders = await window.aivicApi.list(orderTableIndex);
      const products = await window.aivicApi.list(productTableIndex);
      const forecasts = await window.aivicApi.list(forecastTableIndex);

      if (!orders || !products) {
        showError('データの取得に失敗しました');
        return;
      }

      // 店舗IDでフィルタリングし、商品情報と予測情報を結合
      const storeOrders = orders
        .filter(order => order.店舗ID === storeId)
        .map(order => {
          const product = products.find(p => p.商品ID === order.商品ID);
          const forecast = forecasts ? forecasts.find(f => f.商品ID === order.商品ID && f.店舗ID === storeId) : null;

          return {
            ...order,
            商品コード: product?.商品コード || '',
            商品名: product?.商品名|| '',
            仕入先名: '仕入先A', // 実際は仕入先マスタから取得
            予測数量: forecast?.予測数量 || 0
          };
        });

      orderData = storeOrders;
      selectedOrderIds.clear();
      renderOrderList(storeOrders);

    } catch (error) {
      showError('発注データの取得に失敗しました');
    }
  }

  // 全選択チェックボックスの状態を更新
  function updateSelectAllCheckbox() {
    const selectAllCheckbox = container.querySelector('#select-all');
    const orderCheckboxes = container.querySelectorAll('.order-checkbox');
    const checkedCount = container.querySelectorAll('.order-checkbox:checked').length;

    if (orderCheckboxes.length === 0) {
      selectAllCheckbox.checked = false;
      selectAllCheckbox.indeterminate = false;
    } else if (checkedCount === orderCheckboxes.length) {
      selectAllCheckbox.checked = true;
      selectAllCheckbox.indeterminate = false;
    } else if (checkedCount > 0) {
      selectAllCheckbox.checked = false;
      selectAllCheckbox.indeterminate = true;
    } else {
      selectAllCheckbox.checked = false;
      selectAllCheckbox.indeterminate = false;
    }
  }

  // 送信ボタンの状態を更新
  function updateSendButton() {
    const sendButton = container.querySelector('#btn-send');
    const hasSelection = selectedOrderIds.size > 0;
    const hasUnsent = Array.from(selectedOrderIds).some(id => {
      const order = orderData.find(o => o.発注ID === id);
      return order && order.発注ステータス !== '送信済み';
    });

    sendButton.disabled = !hasSelection || !hasUnsent;
  }

  // エラーメッセージを表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');

    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // 成功メッセージを表示
  function showSuccess(message) {
    const resultDiv = container.querySelector('#send-result');
    const messageDiv = container.querySelector('#send-message');
    messageDiv.textContent = message;
    resultDiv.classList.remove('hidden');

    setTimeout(() => {
      resultDiv.classList.add('hidden');
    }, 5000);
  }

  // 発注送信処理
  async function sendOrders() {
    if (selectedOrderIds.size === 0) {
      showError('発注対象が選択されていません');
      return;
    }

    // 送信済みデータの重複チェック
    const selectedOrders = orderData.filter(order => selectedOrderIds.has(order.発注ID));
    const alreadySent = selectedOrders.filter(order => order.発注ステータス === '送信済み');

    if (alreadySent.length > 0) {
      showError('選択された発注データには既に送信済みのものが含まれています');
      return;
    }

    if (!confirm(`${selectedOrderIds.size}件の発注データを送信しますか？`)) {
      return;
    }

    try {
      let successCount = 0;
      let errorCount = 0;

      // 各発注データを順次送信
      for (const orderId of selectedOrderIds) {
        try {
          // 発注ステータスを「送信中」に更新
          await window.aivicApi.update(orderTableIndex, orderId, {
            発注ステータス: '送信中',
            更新日時: new Date().toISOString()
          });

          // 実際の送信処理をシミュレート（通信エラーのテストケース対応）
          if (Math.random() < 0.1) { // 10%の確率で通信エラーをシミュレート
            throw new Error('通信エラーが発生しました');
          }

          // 送信成功時のステータス更新
          await window.aivicApi.update(orderTableIndex, orderId, {
            発注ステータス: '送信済み',
            更新日時: new Date().toISOString()
          });

          successCount++;
        } catch (error) {
          // 送信失敗時のステータス更新
          await window.aivicApi.update(orderTableIndex, orderId, {
            発注ステータス: 'エラー',
            更新日時: new Date().toISOString()
          });
          errorCount++;
        }
      }

      // 結果メッセージの表示
      if (errorCount === 0) {
        showSuccess(`発注データの送信が完了しました（${successCount}件）`);
      } else {
        showError(`送信完了: ${successCount}件、エラー: ${errorCount}件`);
      }

      // データを再読み込み
      selectedOrderIds.clear();
      await loadOrderData(currentStoreId);

    } catch (error) {
      showError('発注送信処理でエラーが発生しました');
    }
  }

  // イベントリスナーの設定

  // 店舗選択
  container.querySelector('#store-select').addEventListener('change', async (e) => {
    currentStoreId = e.target.value;
    await loadOrderData(currentStoreId);
  });

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.order-checkbox');
    checkboxes.forEach(checkbox => {
      checkbox.checked = e.target.checked;
      if (e.target.checked) {
        selectedOrderIds.add(checkbox.dataset.id);
      } else {
        selectedOrderIds.delete(checkbox.dataset.id);
      }
    });
    updateSendButton();
  });

  // 個別チェックボックス
  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('order-checkbox')) {
      const orderId = e.target.dataset.id;
      if (e.target.checked) {
        selectedOrderIds.add(orderId);
      } else {
        selectedOrderIds.delete(orderId);
      }
      updateSelectAllCheckbox();
      updateSendButton();
    }
  });

  // 送信ボタン
  container.querySelector('#btn-send').addEventListener('click', sendOrders);

  // 更新ボタン
  container.querySelector('#btn-refresh').addEventListener('click', async () => {
    if (currentStoreId) {
      await loadOrderData(currentStoreId);
      showSuccess('データを更新しました');
    }
  });

  // 初期化
  initStoreOptions();

  // CSSスタイルを追加
  const style = document.createElement('style');
  style.textContent = `
    .status-badge {
      padding: 0.25rem 0.5rem;
      border-radius: 4px;
      font-size: 0.875rem;
      font-weight: 500;
    }
    .status-sent {
      background: rgba(40, 167, 69, 0.1);
      color: #28a745;
      border: 1px solid #28a745;
    }
    .status-sending {
      background: rgba(255, 193, 7, 0.1);
      color: #ffc107;
      border: 1px solid #ffc107;
    }
    .status-error {
      background: rgba(220, 53, 69, 0.1);
      color: #dc3545;
      border: 1px solid #dc3545;
    }
    .status-pending {
      background: rgba(108, 117, 125, 0.1);
      color: var(--text-muted);
      border: 1px solid var(--border);
    }
    .form-row {
      display: flex;
      gap: 1rem;
      margin-bottom: 1rem;
    }
    .form-group {
      flex: 1;
    }
    .form-group label {
      display: block;
      margin-bottom: 0.5rem;
      color: var(--text);
      font-weight: 500;
    }
    .form-actions {
      border-top: 1px solid var(--border);
      padding-top: 1rem;
    }
  `;
  document.head.appendChild(style);
}

function(container, apiUrl, tables) {
  // 計算結果を格納する配列
  let calculationResults = [];

  // 店舗データを取得してセレクトボックスに設定
  async function loadStores() {
    const stores = await window.aivicApi.list(1); // 店舗マスタのテーブルインデックス
    const storeSelect = container.querySelector('#select-store');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';

    if (stores) {
      stores.forEach(store => {
        const option = document.createElement('option');
        option.value = store.id;
        option.textContent = `${store.店舗名} (${store.店舗コード})`;
        storeSelect.appendChild(option);
      });
    }
  }

  // 計算結果テーブルの再描画
  function renderCalculationResults(results) {
    const tbody = container.querySelector('#calculation-results');
    if (!results || results.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" class="muted">計算結果がありません</td></tr>';
      return;
    }

    tbody.innerHTML = results.map(result => `
      <tr data-id="${result.id}">
        <td>${result.商品名 || ''}</td>
        <td>${result.商品コード || ''}</td>
        <td>${result.現在在庫 || 0}</td>
        <td>${result.予測需要量 || 0}</td>
        <td>${result.安全在庫 || 0}</td>
        <td>${result.発注点 || 0}</td>
        <td>${result.推奨発注量 || 0}</td>
        <td>${result.計算日時 || ''}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${result.id}">詳細</button>
        </td>
      </tr>
    `).join('');
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // 需要予測結果表示
  function showPredictionResult(result) {
    const predictionDiv = container.querySelector('#prediction-result');
    predictionDiv.innerHTML = `
      <div style="color: var(--text);">
        <p><strong>予測需要量:</strong> ${result.予測需要量 || 0} 個</p>
        <p><strong>予測精度:</strong> ${result.予測精度 || 0}%</p>
        <p><strong>推奨発注量:</strong> ${result.推奨発注量 || 0} 個</p>
      </div>
    `;
  }

  // バリデーション
  function validateInputs() {
    const productCode = container.querySelector('#input-product-code').value.trim();
    const currentStock = parseInt(container.querySelector('#input-current-stock').value);
    const predictedDemand = parseInt(container.querySelector('#input-predicted-demand').value);
    const safetyStock = parseInt(container.querySelector('#input-safety-stock').value);
    const orderCycle = parseInt(container.querySelector('#input-order-cycle').value);
    const leadTime = parseInt(container.querySelector('#input-lead-time').value);
    const orderPoint = container.querySelector('#input-order-point').value;

    if (!productCode) {
      showError('商品コードを入力してください');
      return false;
    }

    if (isNaN(currentStock) || currentStock < 0) {
      showError('現在在庫数は0以上の数値を入力してください');
      return false;
    }

    if (isNaN(predictedDemand) || predictedDemand < 0) {
      showError('予測需要量は0以上の数値を入力してください');
      return false;
    }

    if (isNaN(safetyStock) || safetyStock < 0) {
      showError('安全在庫数は0以上の数値を入力してください');
      return false;
    }

    if (isNaN(orderCycle) || orderCycle <= 0) {
      showError('発注サイクルは1以上の数値を入力してください');
      return false;
    }

    if (isNaN(leadTime) || leadTime <= 0) {
      showError('リードタイムは1以上の数値を入力してください');
      return false;
    }

    if (isNaN(parseInt(orderPoint))) {
      showError('発注点は数値を入力してください');
      return false;
    }

    return true;
  }

  // 一括計算のバリデーション
  function validateBulkInputs() {
    const storeSelect = container.querySelector('#select-store');
    const selectedStores = Array.from(storeSelect.selectedOptions).map(option => option.value);
    const category = container.querySelector('#select-category').value;
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;

    if (selectedStores.length === 0 || selectedStores[0] === '') {
      showError('店舗を選択してください');
      return false;
    }

    if (!category) {
      showError('商品カテゴリを選択してください');
      return false;
    }

    if (!startDate || !endDate) {
      showError('計算対象期間を設定してください');
      return false;
    }

    if (new Date(startDate) > new Date(endDate)) {
      showError('開始日は終了日より前の日付を設定してください');
      return false;
    }

    return true;
  }

  // 発注量計算処理
  function calculateOrderQuantity(currentStock, predictedDemand, safetyStock, leadTime, orderCycle) {
    // 発注量 = (予測需要量 × (リードタイム + 発注サイクル) / 発注サイクル) + 安全在庫 - 現在在庫
    const demandDuringLeadTime = predictedDemand * (leadTime + orderCycle) / orderCycle;
    const orderQuantity = Math.max(0, demandDuringLeadTime + safetyStock - currentStock);
    return Math.ceil(orderQuantity);
  }

  // 計算実行ボタンのイベントリスナー
  container.querySelector('#btn-calculate').addEventListener('click', async () => {
    if (!validateInputs()) return;

    const productCode = container.querySelector('#input-product-code').value.trim();
    const currentStock = parseInt(container.querySelector('#input-current-stock').value);
    const predictedDemand = parseInt(container.querySelector('#input-predicted-demand').value);
    const safetyStock = parseInt(container.querySelector('#input-safety-stock').value);
    const orderCycle = parseInt(container.querySelector('#input-order-cycle').value);
    const leadTime = parseInt(container.querySelector('#input-lead-time').value);
    const orderPoint = parseInt(container.querySelector('#input-order-point').value);

    // 発注量計算
    const recommendedOrderQuantity = calculateOrderQuantity(currentStock, predictedDemand, safetyStock, leadTime, orderCycle);

    // 計算結果を作成
    const calculationResult = {
      id: Date.now().toString(),
      商品コード: productCode,
      商品名: `商品_${productCode}`,
      現在在庫: currentStock,
      予測需要量: predictedDemand,
      安全在庫: safetyStock,
      発注点: orderPoint,
      推奨発注量: recommendedOrderQuantity,
      計算日時: new Date().toLocaleString(),
      予測精度: Math.floor(Math.random() * 20) + 80 // 80-99%のランダム値
    };

    // 需要予測結果表示
    showPredictionResult(calculationResult);

    // 計算結果を配列に追加
    calculationResults.push(calculationResult);

    // テーブルを更新
    renderCalculationResults(calculationResults);

    // 需要予測結果テーブルに保存
    await window.aivicApi.save(8, {
      店舗ID: 'store-001',
      商品ID: 'product-001',
      予測対象日: new Date().toISOString(),
      予測数量: predictedDemand,
      予測精度: calculationResult.予測精度,
      推奨発注数量: recommendedOrderQuantity,
      予測モデルバージョン: 'v1.0',
      予測ステータス: '完了',
      発注済フラグ: false
    });
  });

  // 一括計算ボタンのイベントリスナー
  container.querySelector('#btn-bulk-calculate').addEventListener('click', async () => {
    if (!validateBulkInputs()) return;

    const storeSelect = container.querySelector('#select-store');
    const selectedStores = Array.from(storeSelect.selectedOptions).map(option => option.value).filter(v => v);
    const category = container.querySelector('#select-category').value;

    // 複数店舗の一括計算をシミュレート
    const bulkResults = [];
    for (let i = 0; i < selectedStores.length; i++) {
      for (let j = 1; j <= 3; j++) {
        const currentStock = Math.floor(Math.random() * 100) + 10;
        const predictedDemand = Math.floor(Math.random() * 50) + 20;
        const safetyStock = Math.floor(Math.random() * 20) + 5;
        const leadTime = Math.floor(Math.random() * 7) + 1;
        const orderCycle = Math.floor(Math.random() * 5) + 3;

        const recommendedOrderQuantity = calculateOrderQuantity(currentStock, predictedDemand, safetyStock, leadTime, orderCycle);

        bulkResults.push({
          id: `bulk-${Date.now()}-${i}-${j}`,
          商品コード: `${category}-${String(j).padStart(3, '0')}`,
          商品名: `${category}商品${j}`,
          現在在庫: currentStock,
          予測需要量: predictedDemand,
          安全在庫: safetyStock,
          発注点: Math.floor(predictedDemand * leadTime / 7) + safetyStock,
          推奨発注量: recommendedOrderQuantity,
          計算日時: new Date().toLocaleString(),
          予測精度: Math.floor(Math.random() * 20) + 80
        });
      }
    }

    // 計算結果を配列に追加
    calculationResults.push(...bulkResults);

    // テーブルを更新
    renderCalculationResults(calculationResults);

    // 需要予測結果表示（最初の結果を表示）
    if (bulkResults.length > 0) {
      showPredictionResult(bulkResults[0]);
    }
  });

  // 発注データ生成ボタンのイベントリスナー
  container.querySelector('#btn-generate-order').addEventListener('click', async () => {
    if (calculationResults.length === 0) {
      showError('計算結果がありません。先に発注量計算を実行してください');
      return;
    }

    if (!confirm('計算結果に基づいて発注データを生成しますか？')) return;

    // 発注データを生成
    for (const result of calculationResults) {
      if (result.推奨発注量 > 0) {
        const orderData = {
          店舗ID: 'store-001',
          商品ID: 'product-001',
          発注日: new Date().toISOString(),
          納期予定日: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
          発注数量: result.推奨発注量,
          予測数量: result.予測需要量,
          発注単価: Math.floor(Math.random() * 500) + 100,
          発注金額: result.推奨発注量 * (Math.floor(Math.random() * 500) + 100),
          発注方法: 'AI自動発注',
          発注ステータス: '発注済',
          仕入先ID: 'supplier-001',
          発注理由: 'AI需要予測に基づく自動発注',
          自動発注フラグ: true
        };

        await window.aivicApi.save(9, orderData);
      }
    }

    alert('発注データの生成が完了しました');

    // 発注管理画面に遷移
    window.showScreen('scr-1778591852463');
  });

  // 詳細ボタンのイベントデリゲーション
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const resultId = detailBtn.dataset.id;
      const result = calculationResults.find(r => r.id === resultId);
      if (result) {
        showPredictionResult(result);
      }
    }
  });

  // 初期化処理
  loadStores();
  renderCalculationResults([]);

  // 初期日付設定
  const today = new Date();
  const tomorrow = new Date(today);
  tomorrow.setDate(tomorrow.getDate() + 1);

  container.querySelector('#input-start-date').value = today.toISOString().split('T')[0];
  container.querySelector('#input-end-date').value = tomorrow.toISOString().split('T')[0];
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#inventory-tbody");
  const storeSelect = container.querySelector("#store-select");
  const categoryFilter = container.querySelector("#category-filter");
  const productNameSearch = container.querySelector("#product-name-search");
  const productCodeSearch = container.querySelector("#product-code-search");
  const stockStatusFilter = container.querySelector("#stock-status-filter");
  const errorMessage = container.querySelector("#error-message");
  const noResults = container.querySelector("#no-results");
  const resultCount = container.querySelector("#result-count");

  let allInventoryData = [];
  let storesData = [];
  let productsData = [];

  // エラーメッセージ表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove("hidden");
    setTimeout(() => {
      errorMessage.classList.add("hidden");
    }, 5000);
  }

  // 在庫状況判定関数
  function getStockStatus(currentStock, safetyStock, orderPoint) {
    if (currentStock <= orderPoint) return "不足";
    if (currentStock > safetyStock * 2) return "過剰";
    return "適正";
  }

  // 在庫一覧テーブル再描画関数
  function renderInventoryRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = "";
      noResults.classList.remove("hidden");
      resultCount.textContent = "0件";
      return;
    }

    noResults.classList.add("hidden");
    resultCount.textContent = `${rows.length}件`;

    tbody.innerHTML = rows.map(row => {
      const product = productsData.find(p => p.商品ID === row.商品ID) || {};
      const currentStock = row.現在在庫数 || 0;
      const safetyStock = row.安全在庫数 || 0;
      const orderPoint = row.発注点 || 0;
      const stockStatus = getStockStatus(currentStock, safetyStock, orderPoint);

      let statusColor = "";
      if (stockStatus === "不足") statusColor = "color: #dc3545;";
      else if (stockStatus === "過剰") statusColor = "color: #fd7e14;";
      else statusColor = "color: #28a745;";

      return `
        <tr data-id="${row.在庫ID || row.id || ''}">
          <td>${product.商品コード || ""}</td>
          <td>${product.商品名 || ""}</td>
          <td style="text-align: right;">${currentStock.toLocaleString()}</td>
          <td style="text-align: right;">${safetyStock.toLocaleString()}</td>
          <td style="text-align: right;">${orderPoint.toLocaleString()}</td>
          <td>${row.最終入荷日 ? new Date(row.最終入荷日).toLocaleDateString('ja-JP') : ""}</td>
          <td style="${statusColor} font-weight: bold;">${stockStatus}</td>
        </tr>
      `;
    }).join("");
  }

  // 店舗選択肢を設定
  function setupStoreOptions() {
    if (storesData.length > 0) {
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
        storesData.map(store => `<option value="${store.店舗ID}">${store.店舗名}</option>`).join("");
    }
  }

  // 検索フィルタリング関数
  function filterInventoryData() {
    const selectedStoreId = storeSelect.value;
    const selectedCategory = categoryFilter.value;
    const productNameKeyword = productNameSearch.value.trim().toLowerCase();
    const productCodeKeyword = productCodeSearch.value.trim().toLowerCase();
    const selectedStockStatus = stockStatusFilter.value;

    if (!selectedStoreId) {
      showError("店舗を選択してください");
      renderInventoryRows([]);
      return;
    }

    // 入力値検証
    if (productNameKeyword.length > 255) {
      showError("商品名は255文字以内で入力してください");
      return;
    }

    if (productCodeKeyword.length > 20) {
      showError("商品コードは20文字以内で入力してください");
      return;
    }

    // 特殊文字チェック
    const dangerousChars = /<script|javascript:|on\w+=/i;
    if (dangerousChars.test(productNameKeyword) || dangerousChars.test(productCodeKeyword)) {
      showError("不正な文字が含まれています");
      return;
    }

    let filteredData = allInventoryData.filter(item => {
      // 店舗フィルタ
      if (item.店舗ID !== selectedStoreId) return false;

      // 商品情報取得
      const product = productsData.find(p => p.商品ID === item.商品ID) || {};

      // カテゴリフィルタ
      if (selectedCategory && product.商品カテゴリ !== selectedCategory) return false;

      // 商品名フィルタ
      if (productNameKeyword && !product.商品名?.toLowerCase().includes(productNameKeyword)) return false;

      // 商品コードフィルタ
      if (productCodeKeyword && !product.商品コード?.toLowerCase().includes(productCodeKeyword)) return false;

      // 在庫状況フィルタ
      if (selectedStockStatus) {
        const currentStock = item.現在在庫数 || 0;
        const safetyStock = item.安全在庫数 || 0;
        const orderPoint = item.発注点 || 0;
        const stockStatus = getStockStatus(currentStock, safetyStock, orderPoint);
        if (stockStatus !== selectedStockStatus) return false;
      }

      return true;
    });

    renderInventoryRows(filteredData);
  }

  // CSVエクスポート関数
  function exportToCSV() {
    const selectedStoreId = storeSelect.value;
    if (!selectedStoreId) {
      showError("店舗を選択してからエクスポートしてください");
      return;
    }

    const headers = ["商品コード", "商品名", "現在在庫数", "安全在庫数", "発注点", "最終入荷日", "在庫状況"];
    const csvData = allInventoryData
      .filter(item => item.店舗ID === selectedStoreId)
      .map(item => {
        const product = productsData.find(p => p.商品ID === item.商品ID) || {};
        const currentStock = item.現在在庫数 || 0;
        const safetyStock = item.安全在庫数 || 0;
        const orderPoint = item.発注点 || 0;
        const stockStatus = getStockStatus(currentStock, safetyStock, orderPoint);

        return [
          product.商品コード || "",
          product.商品名 || "",
          currentStock,
          safetyStock,
          orderPoint,
          item.最終入荷日 ? new Date(item.最終入荷日).toLocaleDateString('ja-JP') : "",
          stockStatus
        ];
      });

    const csvContent = "\uFEFF" + [headers, ...csvData]
      .map(row => row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(","))
      .join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `在庫一覧_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 店舗データ読み込み
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (stores) {
        storesData = stores;
        setupStoreOptions();
      }

      // 商品データ読み込み
      const products = await window.aivicApi.list(2); // 商品マスタ
      if (products) {
        productsData = products;
      }

      // 在庫データ読み込み（サンプルデータとして売上実績データを使用）
      const inventoryData = await window.aivicApi.list(3); // 売上実績データ
      if (inventoryData) {
        // 在庫データのサンプル生成（実際のシステムでは在庫テーブルから取得）
        allInventoryData = inventoryData.map((item, index) => ({
          在庫ID: `INV${String(index + 1).padStart(6, '0')}`,
          店舗ID: item.店舗ID,
          商品ID: item.商品ID,
          現在在庫数: Math.floor(Math.random() * 500) + 10,
          安全在庫数: Math.floor(Math.random() * 100) + 20,
          発注点: Math.floor(Math.random() * 50) + 10,
          最終入荷日: new Date(Date.now() - Math.random() * 30 * 24 * 60 * 60 * 1000).toISOString()
        }));
      }

      // 初期表示（全件は表示しない）
      renderInventoryRows([]);
    } catch (error) {
      console.error("データ読み込みエラー:", error);
      showError("データの読み込みに失敗しました");
    }
  }

  // イベントリスナー設定
  container.querySelector("#btn-search").addEventListener("click", filterInventoryData);

  container.querySelector("#btn-clear").addEventListener("click", () => {
    storeSelect.value = "";
    categoryFilter.value = "";
    productNameSearch.value = "";
    productCodeSearch.value = "";
    stockStatusFilter.value = "";
    renderInventoryRows([]);
    errorMessage.classList.add("hidden");
  });

  container.querySelector("#btn-export").addEventListener("click", exportToCSV);

  // Enter キーで検索実行
  [productNameSearch, productCodeSearch].forEach(input => {
    input.addEventListener("keypress", (e) => {
      if (e.key === "Enter") {
        filterInventoryData();
      }
    });
  });

  // 初期データ読み込み実行
  loadInitialData();
}

function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const STORES_TABLE = 1; // 店舗マスタ
  const PRODUCTS_TABLE = 2; // 商品マスタ
  const FORECAST_TABLE = 9; // 需要予測結果
  const ORDERS_TABLE = 10; // 発注データ

  let currentForecastData = [];
  let storesData = [];
  let productsData = [];

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#order-date').value = today;

  // 納期予定日を3日後に設定
  const deliveryDate = new Date();
  deliveryDate.setDate(deliveryDate.getDate() + 3);
  container.querySelector('#delivery-date').value = deliveryDate.toISOString().split('T')[0];

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => errorDiv.classList.add('hidden'), 5000);
  }

  // 合計金額計算・表示
  function updateTotalAmount() {
    let total = 0;
    container.querySelectorAll('.order-quantity-input').forEach(input => {
      const quantity = parseInt(input.value) || 0;
      const price = parseInt(input.dataset.price) || 0;
      total += quantity * price;
    });
    container.querySelector('#total-amount').textContent = '¥' + total.toLocaleString();
  }

  // 発注数量入力フィールドのイベントハンドラ
  function setupQuantityInput(input) {
    input.addEventListener('input', function() {
      const quantity = parseInt(this.value) || 0;
      const price = parseInt(this.dataset.price) || 0;
      const amountCell = this.closest('tr').querySelector('.order-amount');
      amountCell.textContent = '¥' + (quantity * price).toLocaleString();
      updateTotalAmount();
    });

    input.addEventListener('blur', function() {
      // 数値バリデーション
      const value = this.value.trim();
      if (value !== '' && (isNaN(value) || parseInt(value) < 0)) {
        showError('発注数量は0以上の数値を入力してください');
        this.focus();
      }
    });
  }

  // 需要予測結果テーブル描画
  function renderForecastTable(data) {
    const tbody = container.querySelector('#forecast-tbody');

    if (!data || data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" style="text-align: center; color: var(--text-muted); padding: 40px;">該当するデータがありません</td></tr>';
      updateTotalAmount();
      return;
    }

    tbody.innerHTML = data.map(item => {
      const product = productsData.find(p => p.商品ID === item.商品ID) || {};
      const orderAmount = 0; // 初期値は0

      return `
        <tr data-product-id="${item.商品ID}">
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>${product.商品カテゴリID || ''}</td>
          <td style="text-align: right;">${item.予測数量 || 0}</td>
          <td style="text-align: right;">${item.推奨発注数量 || 0}</td>
          <td style="text-align: right;">${Math.floor(Math.random() * 100)}</td>
          <td>
            <input type="number" 
                   class="input order-quantity-input" 
                   min="0" 
                   value="0"
                   data-price="${product.単価 || 0}"
                   style="width: 80px; text-align: right;" />
          </td>
          <td style="text-align: right;">¥${(product.単価 || 0).toLocaleString()}</td>
          <td class="order-amount" style="text-align: right;">¥0</td>
        </tr>
      `;
    }).join('');

    // 発注数量入力フィールドにイベントハンドラを設定
    container.querySelectorAll('.order-quantity-input').forEach(setupQuantityInput);
    updateTotalAmount();
  }

  // 店舗選択肢を設定
  async function loadStores() {
    storesData = await window.aivicApi.list(STORES_TABLE);
    if (storesData) {
      const storeSelect = container.querySelector('#store-select');
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
        storesData.filter(store => store.有効フラグ)
          .map(store => `<option value="${store.店舗ID}">${store.店舗名}</option>`)
          .join('');
    }
  }

  // 商品カテゴリ選択肢を設定
  async function loadCategories() {
    productsData = await window.aivicApi.list(PRODUCTS_TABLE);
    if (productsData) {
      const categories = [...new Set(productsData.map(p => p.商品カテゴリID))].filter(Boolean);
      const categorySelect = container.querySelector('#category-filter');
      categorySelect.innerHTML = '<option value="">全てのカテゴリ</option>' +
        categories.map(cat => `<option value="${cat}">${cat}</option>`).join('');
    }
  }

  // 需要予測データ読み込み・表示
  async function loadForecastData() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const category = container.querySelector('#category-filter').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    if (!orderDate) {
      showError('発注日付を選択してください');
      return;
    }

    // 過去日付チェック
    if (orderDate < today) {
      showError('発注日付には本日以降の日付を選択してください');
      return;
    }

    const forecastData = await window.aivicApi.list(FORECAST_TABLE);
    if (forecastData) {
      let filteredData = forecastData.filter(item => 
        item.店舗ID === storeId && 
        item.予測ステータス === '完了'
      );

      // カテゴリフィルター適用
      if (category) {
        const categoryProducts = productsData.filter(p => p.商品カテゴリID === category);
        const categoryProductIds = categoryProducts.map(p => p.商品ID);
        filteredData = filteredData.filter(item => categoryProductIds.includes(item.商品ID));
      }

      currentForecastData = filteredData;
      renderForecastTable(filteredData);
    }
  }

  // 推奨発注数量で一括入力
  function bulkSetRecommended() {
    if (confirm('全ての商品の発注数量を推奨数量で設定しますか？')) {
      container.querySelectorAll('.order-quantity-input').forEach(input => {
        const row = input.closest('tr');
        const recommendedQty = row.cells[4].textContent.trim();
        input.value = recommendedQty;
        input.dispatchEvent(new Event('input'));
      });
    }
  }

  // 全数量クリア
  function clearAllQuantities() {
    if (confirm('全ての発注数量をクリアしますか？')) {
      container.querySelectorAll('.order-quantity-input').forEach(input => {
        input.value = '0';
        input.dispatchEvent(new Event('input'));
      });
    }
  }

  // 発注承認処理
  async function approveOrders() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const deliveryDate = container.querySelector('#delivery-date').value;
    const orderReason = container.querySelector('#order-reason').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    if (!orderDate) {
      showError('発注日付を選択してください');
      return;
    }

    if (!deliveryDate) {
      showError('納期予定日を選択してください');
      return;
    }

    // 発注数量が入力されている商品を収集
    const orderItems = [];
    container.querySelectorAll('.order-quantity-input').forEach(input => {
      const quantity = parseInt(input.value) || 0;
      if (quantity >= 0) { // 0も許可
        const row = input.closest('tr');
        const productId = row.dataset.productId;
        const product = productsData.find(p => p.商品ID === productId);
        const forecastItem = currentForecastData.find(f => f.商品ID === productId);

        if (product) {
          orderItems.push({
            店舗ID: storeId,
            商品ID: productId,
            需要予測結果ID: forecastItem?.予測結果ID || null,
            発注日: orderDate + 'T00:00:00Z',
            納期予定日: deliveryDate + 'T00:00:00Z',
            発注数量: quantity,
            予測数量: forecastItem?.推奨発注数量 || 0,
            発注単価: product.単価 || 0,
            発注金額: quantity * (product.単価 || 0),
            発注方法: quantity === (forecastItem?.推奨発注数量 || 0) ? 'AI推奨採用' : 'AI推奨修正',
            発注ステータス: '承認済み',
            仕入先ID: product.仕入先ID || '',
            発注理由: orderReason || 'AI需要予測に基づく発注',
            承認者ID: 'current-user-id',
            承認日時: new Date().toISOString(),
            自動発注フラグ: false,
            作成者ID: 'current-user-id',
            更新者ID: 'current-user-id'
          });
        }
      }
    });

    if (orderItems.length === 0) {
      showError('発注数量が入力されている商品がありません');
      return;
    }

    if (!confirm(`${orderItems.length}件の商品を発注しますか？\n合計金額: ${container.querySelector('#total-amount').textContent}`)) {
      return;
    }

    // 発注データを保存
    let successCount = 0;
    for (const item of orderItems) {
      const saved = await window.aivicApi.save(ORDERS_TABLE, item);
      if (saved) successCount++;
    }

    if (successCount === orderItems.length) {
      alert(`発注が完了しました。${successCount}件の商品を発注しました。`);
      // 発注数量をクリア
      clearAllQuantities();
    } else {
      showError(`発注処理中にエラーが発生しました。${successCount}/${orderItems.length}件が正常に処理されました。`);
    }
  }

  // 予測結果更新
  async function updateForecast() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    if (!orderDate) {
      showError('発注日付を選択してください');
      return;
    }

    // 予測結果を再読み込み
    await loadForecastData();
    alert('需要予測結果を更新しました');
  }

  // イベントリスナー設定
  container.querySelector('#btn-display').addEventListener('click', loadForecastData);
  container.querySelector('#btn-update-forecast').addEventListener('click', updateForecast);
  container.querySelector('#btn-bulk-recommended').addEventListener('click', bulkSetRecommended);
  container.querySelector('#btn-clear-all').addEventListener('click', clearAllQuantities);
  container.querySelector('#btn-approve').addEventListener('click', approveOrders);
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    if (confirm('入力内容をクリアしますか？')) {
      clearAllQuantities();
    }
  });

  // カテゴリフィルター変更時の再表示
  container.querySelector('#category-filter').addEventListener('change', () => {
    if (currentForecastData.length > 0) {
      loadForecastData();
    }
  });

  // 初期データ読み込み
  loadStores();
  loadCategories();
}

function(container, apiUrl, tables) {
  let editingModelId = null;

  // テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector("#model-list-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.モデル名 || ""}</td>
        <td>${r.対象店舗名 || ""}</td>
        <td>${r.対象商品カテゴリ || ""}</td>
        <td>${r.アルゴリズム || ""}</td>
        <td>${r.モデル精度目標値 || ""}%</td>
        <td><span class="status-badge ${r.ステータス === '作成完了' ? 'success' : 'pending'}">${r.ステータス || ""}</span></td>
        <td>${r.作成日時 ? new Date(r.作成日時).toLocaleDateString() : ""}</td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${r.id}">編集</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 店舗データを読み込んでセレクトボックスに設定
  async function loadStores() {
    const stores = await window.aivicApi.list(1); // 店舗マスタ
    const storeSelect = container.querySelector("#target-store");
    if (stores) {
      storeSelect.innerHTML = '<option value="">選択してください</option>' + 
        stores.map(store => `<option value="${store.id}">${store.店舗名}</option>`).join("");
    }
  }

  // 商品カテゴリのチェックボックスを生成
  function loadCategories() {
    const categories = ["食品", "飲料", "日用品", "衣料品", "家電", "書籍", "その他"];
    const categoryContainer = container.querySelector("#category-checkboxes");
    categoryContainer.innerHTML = categories.map(cat => `
      <label class="checkbox-item">
        <input type="checkbox" name="product-category" value="${cat}"> ${cat}
      </label>
    `).join("");
  }

  // フォームリセット
  function resetForm() {
    const form = container.querySelector("#model-form");
    form.reset();
    editingModelId = null;
    container.querySelector("#edit-model-id").value = "";
    container.querySelector("#form-title").textContent = "新規モデル作成";
    container.querySelector("#btn-save").textContent = "モデル作成";

    // チェックボックスをリセット
    container.querySelectorAll('input[type="checkbox"]').forEach(cb => cb.checked = false);
    container.querySelector('input[name="prediction-period"][value="30"]').checked = true;
  }

  // フォームにデータを設定（編集時）
  function populateForm(model) {
    container.querySelector("#model-name").value = model.モデル名 || "";
    container.querySelector("#target-store").value = model.対象店舗ID || "";
    container.querySelector("#learning-start-date").value = model.学習期間開始日 || "";
    container.querySelector("#learning-end-date").value = model.学習期間終了日 || "";

    if (model.予測期間) {
      const periodRadio = container.querySelector(`input[name="prediction-period"][value="${model.予測期間}"]`);
      if (periodRadio) periodRadio.checked = true;
    }

    container.querySelector("#algorithm").value = model.アルゴリズム || "ARIMA";
    container.querySelector("#learning-rate").value = model.学習率 || 0.01;
    container.querySelector("#learning-rate-value").textContent = model.学習率 || 0.01;
    container.querySelector("#accuracy-target").value = model.モデル精度目標値 || 85;
    container.querySelector("#notification-email").value = model.通知メールアドレス || "";

    // データソースのチェックボックス
    if (model.使用データソース) {
      const dataSources = model.使用データソース.split(",");
      dataSources.forEach(ds => {
        const checkbox = container.querySelector(`input[name="data-source"][value="${ds.trim()}"]`);
        if (checkbox) checkbox.checked = true;
      });
    }

    container.querySelector("#form-title").textContent = "モデル編集";
    container.querySelector("#btn-save").textContent = "更新";
  }

  // バリデーション
  function validateForm() {
    const modelName = container.querySelector("#model-name").value.trim();
    const targetStore = container.querySelector("#target-store").value;
    const startDate = container.querySelector("#learning-start-date").value;
    const endDate = container.querySelector("#learning-end-date").value;
    const accuracyTarget = parseInt(container.querySelector("#accuracy-target").value);

    // 必須項目チェック
    if (!modelName) {
      alert("モデル名を入力してください");
      return false;
    }

    if (!targetStore) {
      alert("対象店舗を選択してください");
      return false;
    }

    // 商品カテゴリ選択チェック
    const selectedCategories = container.querySelectorAll('input[name="product-category"]:checked');
    if (selectedCategories.length === 0) {
      alert("商品カテゴリを選択してください");
      return false;
    }

    // データソース選択チェック
    const selectedDataSources = container.querySelectorAll('input[name="data-source"]:checked');
    if (selectedDataSources.length === 0) {
      alert("データソースを選択してください");
      return false;
    }

    // 学習期間チェック
    if (startDate && endDate) {
      const start = new Date(startDate);
      const end = new Date(endDate);
      const today = new Date();

      if (start > today || end > today) {
        alert("学習期間に未来の日付は設定できません");
        return false;
      }

      if (start >= end) {
        alert("学習期間の開始日は終了日より前の日付を設定してください");
        return false;
      }
    }

    // 精度目標値チェック
    if (accuracyTarget < 0 || accuracyTarget > 100) {
      alert("精度目標値は0%から100%の範囲で入力してください");
      return false;
    }

    return true;
  }

  // 初期データ表示
  renderRows(tables[0].records || []);

  // 店舗とカテゴリデータを読み込み
  loadStores();
  loadCategories();

  // 学習率スライダーの値表示更新
  container.querySelector("#learning-rate").addEventListener("input", (e) => {
    container.querySelector("#learning-rate-value").textContent = e.target.value;
  });

  // 全選択チェックボックス（カテゴリ）
  container.querySelector("#select-all-categories").addEventListener("change", (e) => {
    const checkboxes = container.querySelectorAll('input[name="product-category"]');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // 全選択チェックボックス（データソース）
  container.querySelector("#select-all-datasources").addEventListener("change", (e) => {
    const checkboxes = container.querySelectorAll('input[name="data-source"]');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // 検索機能
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const keyword = container.querySelector("#input-search").value.toLowerCase();
    const rows = await window.aivicApi.list(0);
    if (rows) {
      const filtered = rows.filter(r => 
        JSON.stringify(r).toLowerCase().includes(keyword)
      );
      renderRows(filtered);
    }
  });

  // CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0);
    if (rows) {
      const headers = ["モデル名", "対象店舗", "アルゴリズム", "予測精度目標", "ステータス", "作成日時"];
      const csvContent = "\uFEFF" + [
        headers.join(","),
        ...rows.map(r => [
          `"${r.モデル名 || ""}"`,
          `"${r.対象店舗名 || ""}"`,
          `"${r.アルゴリズム || ""}"`,
          `"${r.モデル精度目標値 || ""}%"`,
          `"${r.ステータス || ""}"`,
          `"${r.作成日時 ? new Date(r.作成日時).toLocaleDateString() : ""}"`
        ].join(","))
      ].join("\n");

      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = "model_settings_export.csv";
      link.click();
    }
  });

  // 新規作成ボタン
  container.querySelector("#btn-new-model").addEventListener("click", () => {
    resetForm();
  });

  // キャンセルボタン
  container.querySelector("#btn-cancel").addEventListener("click", () => {
    resetForm();
  });

  // フォーム送信
  container.querySelector("#model-form").addEventListener("submit", async (e) => {
    e.preventDefault();

    if (!validateForm()) return;

    const formData = {
      モデル名: container.querySelector("#model-name").value.trim(),
      対象店舗ID: container.querySelector("#target-store").value,
      対象店舗名: container.querySelector("#target-store").selectedOptions[0]?.textContent || "",
      対象商品カテゴリ: Array.from(container.querySelectorAll('input[name="product-category"]:checked')).map(cb => cb.value).join(", "),
      学習期間開始日: container.querySelector("#learning-start-date").value,
      学習期間終了日: container.querySelector("#learning-end-date").value,
      予測期間: container.querySelector('input[name="prediction-period"]:checked')?.value || "30",
      使用データソース: Array.from(container.querySelectorAll('input[name="data-source"]:checked')).map(cb => cb.value).join(", "),
      アルゴリズム: container.querySelector("#algorithm").value,
      学習率: parseFloat(container.querySelector("#learning-rate").value),
      モデル精度目標値: parseInt(container.querySelector("#accuracy-target").value),
      通知メールアドレス: container.querySelector("#notification-email").value,
      ステータス: "作成完了",
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };

    let result;
    if (editingModelId) {
      result = await window.aivicApi.update(0, editingModelId, formData);
    } else {
      result = await window.aivicApi.save(0, formData);
    }

    if (result) {
      alert(editingModelId ? "モデルの更新が完了しました" : "モデルの作成が完了しました");
      resetForm();
      const updatedRows = await window.aivicApi.list(0);
      if (updatedRows) renderRows(updatedRows);
    }
  });

  // 行レベル操作（編集・削除）
  container.addEventListener("click", async (e) => {
    const deleteBtn = e.target.closest(".delete-btn");
    const editBtn = e.target.closest(".edit-btn");

    if (deleteBtn) {
      if (!confirm("このモデルを削除しますか？")) return;

      const id = deleteBtn.dataset.id;
      await window.aivicApi.delete(0, id);
      const rows = await window.aivicApi.list(0);
      if (rows) renderRows(rows);
    }

    if (editBtn) {
      const id = editBtn.dataset.id;
      const rows = await window.aivicApi.list(0);
      if (rows) {
        const model = rows.find(r => r.id === id);
        if (model) {
          editingModelId = id;
          container.querySelector("#edit-model-id").value = id;
          populateForm(model);
        }
      }
    }
  });
}

function(container, apiUrl, tables) {
  // テスト履歴の再描画関数
  function renderTestHistory(rows) {
    const tbody = container.querySelector("#test-history-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${new Date(r.実行日時 || Date.now()).toLocaleString()}</td>
        <td>${r.モデル名 || ""}</td>
        <td>${r.テスト期間開始日 || ""} ～ ${r.テスト期間終了日 || ""}</td>
        <td>${r.対象店舗数 || 0}</td>
        <td>${r.MAPE || "N/A"}%</td>
        <td>${r.RMSE || "N/A"}</td>
        <td>${r.実行時間秒 || 0}秒</td>
        <td>
          <button class="action-btn secondary view-btn" data-id="${r.id}">詳細</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 初期データ表示
  renderTestHistory(tables[0]?.records || []);

  // 全店舗選択チェックボックス
  const selectAllStores = container.querySelector("#select-all-stores");
  const storeCheckboxes = container.querySelectorAll('input[name="stores"]');

  selectAllStores.addEventListener("change", function() {
    storeCheckboxes.forEach(cb => cb.checked = this.checked);
  });

  // 実績値vs予測値グラフ描画
  function drawComparisonChart(actualData, predictedData) {
    const canvas = container.querySelector("#comparison-chart");
    const ctx = canvas.getContext("2d");

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // グラフの設定
    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸を描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // データがある場合のみグラフを描画
    if (actualData && actualData.length > 0) {
      const maxValue = Math.max(...actualData, ...predictedData);
      const minValue = Math.min(...actualData, ...predictedData);
      const valueRange = maxValue - minValue || 1;

      // 実績値の線
      ctx.strokeStyle = '#4a90e2';
      ctx.lineWidth = 2;
      ctx.beginPath();
      actualData.forEach((value, index) => {
        const x = padding + (index / (actualData.length - 1)) * chartWidth;
        const y = canvas.height - padding - ((value - minValue) / valueRange) * chartHeight;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.stroke();

      // 予測値の線
      ctx.strokeStyle = '#f5a623';
      ctx.lineWidth = 2;
      ctx.setLineDash([5, 5]);
      ctx.beginPath();
      predictedData.forEach((value, index) => {
        const x = padding + (index / (predictedData.length - 1)) * chartWidth;
        const y = canvas.height - padding - ((value - minValue) / valueRange) * chartHeight;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.stroke();
      ctx.setLineDash([]);
    }

    // 凡例
    ctx.fillStyle = '#d0e4ff';
    ctx.font = '14px Arial';
    ctx.fillText('実績値', padding + 20, 30);
    ctx.fillText('予測値', padding + 100, 30);

    ctx.strokeStyle = '#4a90e2';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(padding, 25);
    ctx.lineTo(padding + 15, 25);
    ctx.stroke();

    ctx.strokeStyle = '#f5a623';
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    ctx.moveTo(padding + 80, 25);
    ctx.lineTo(padding + 95, 25);
    ctx.stroke();
    ctx.setLineDash([]);
  }

  // テスト実行ボタン
  container.querySelector("#btn-execute-test").addEventListener("click", async function() {
    const model = container.querySelector("#select-model").value;
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;
    const category = container.querySelector("#select-category").value;
    const selectedStores = Array.from(container.querySelectorAll('input[name="stores"]:checked')).map(cb => cb.value);
    const dataset = container.querySelector('input[name="dataset"]:checked')?.value;

    // バリデーション
    if (!model) {
      alert("予測モデルが選択されていません");
      return;
    }
    if (!dataset) {
      alert("テストデータセットが選択されていません");
      return;
    }
    if (!startDate || !endDate) {
      alert("テスト期間を設定してください");
      return;
    }
    if (new Date(endDate) < new Date(startDate)) {
      alert("終了日は開始日より後の日付を設定してください");
      return;
    }
    if (selectedStores.length === 0) {
      alert("対象店舗を選択してください");
      return;
    }
    if (!category) {
      alert("商品カテゴリが未選択です");
      return;
    }

    // テスト実行開始
    const startTime = Date.now();
    this.disabled = true;
    this.textContent = "テスト実行中...";

    try {
      // モックデータでテスト結果を生成
      await new Promise(resolve => setTimeout(resolve, 2000)); // 実行時間をシミュレート

      const executionTime = Math.round((Date.now() - startTime) / 1000);
      const mape = (Math.random() * 15 + 5).toFixed(2); // 5-20%
      const rmse = (Math.random() * 50 + 10).toFixed(2); // 10-60

      // 結果表示
      container.querySelector("#mape-value").textContent = mape;
      container.querySelector("#rmse-value").textContent = rmse;
      container.querySelector("#execution-time").textContent = executionTime;

      // モデルパラメータ表示
      container.querySelector("#param-learning-rate").textContent = "0.001";
      container.querySelector("#param-epochs").textContent = "100";
      container.querySelector("#param-batch-size").textContent = "32";
      container.querySelector("#param-hidden-layers").textContent = "3";

      // グラフ描画（サンプルデータ）
      const actualData = Array.from({length: 30}, () => Math.random() * 100 + 50);
      const predictedData = actualData.map(v => v + (Math.random() - 0.5) * 20);
      drawComparisonChart(actualData, predictedData);

      // 結果エリア表示
      container.querySelector("#test-results").classList.remove("hidden");

      // テスト履歴に保存
      const testResult = {
        モデル名: model,
        テスト期間開始日: startDate,
        テスト期間終了日: endDate,
        対象店舗数: selectedStores.length,
        MAPE: parseFloat(mape),
        RMSE: parseFloat(rmse),
        実行時間秒: executionTime,
        実行日時: new Date().toISOString(),
        データセット種別: dataset,
        商品カテゴリ: category
      };

      const saved = await window.aivicApi.save(0, testResult);
      if (saved) {
        const rows = await window.aivicApi.list(0);
        if (rows) renderTestHistory(rows);
      }

    } catch (error) {
      alert("テスト実行中にエラーが発生しました: " + error.message);
    } finally {
      this.disabled = false;
      this.textContent = "テスト実行";
    }
  });

  // テスト結果エクスポート
  container.querySelector("#btn-export-results").addEventListener("click", function() {
    const mape = container.querySelector("#mape-value").textContent;
    const rmse = container.querySelector("#rmse-value").textContent;
    const executionTime = container.querySelector("#execution-time").textContent;

    const csvContent = [
      "項目,値",
      `MAPE,${mape}`,
      `RMSE,${rmse}`,
      `実行時間,${executionTime}`,
      `エクスポート日時,${new Date().toLocaleString()}`
    ].join("\n");

    const blob = new Blob(["\uFEFF" + csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `model_test_results_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // テスト履歴の操作（削除・詳細表示）
  container.addEventListener("click", async function(e) {
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("このテスト履歴を削除しますか？")) return;

      await window.aivicApi.delete(0, deleteBtn.dataset.id);
      const rows = await window.aivicApi.list(0);
      if (rows) renderTestHistory(rows);
      return;
    }

    const viewBtn = e.target.closest(".view-btn");
    if (viewBtn) {
      alert("詳細表示機能は今後実装予定です");
      return;
    }
  });

  // 初期グラフ描画（空のグラフ）
  drawComparisonChart([], []);
}

function(container, apiUrl, tables) {
