    const storeList = container.querySelector('#store-list');

    if (stores) {
      const activeStores = stores.filter(s => s.有効フラグ);
      storeList.innerHTML = activeStores.map(store => `
        <label style="display: flex; align-items: center; gap: 8px; margin-bottom: 8px; cursor: pointer;">
          <input type="checkbox" class="store-checkbox" value="${store.店舗ID}" style="margin: 0;">
          <span style="color: var(--text); font-size: 14px;">${store.店舗名} (${store.店舗コード})</span>
        </label>
      `).join('');
    }
  }

  // モデル詳細情報を表示
  async function showModelDetails(modelId) {
    const models = await window.aivicApi.list(8);
    if (!models) return;

    const model = models.find(m => m.予測結果ID === modelId);
    if (!model) return;

    const detailsArea = container.querySelector('#model-details');
    const modelInfo = container.querySelector('#model-info');

    modelInfo.innerHTML = `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 16px;">
        <div>
          <div style="margin-bottom: 8px;"><strong>モデルバージョン:</strong> ${model.予測モデルバージョン}</div>
          <div style="margin-bottom: 8px;"><strong>予測精度:</strong> ${model.予測精度 || 'N/A'}%</div>
          <div style="margin-bottom: 8px;"><strong>作成日時:</strong> ${new Date(model.作成日時).toLocaleString()}</div>
        </div>
        <div>
          <div style="margin-bottom: 8px;"><strong>ステータス:</strong> ${model.予測ステータス}</div>
          <div style="margin-bottom: 8px;"><strong>対象商品:</strong> ${model.商品ID ? '個別商品' : '全商品'}</div>
          <div style="margin-bottom: 8px;"><strong>備考:</strong> ${model.備考 || 'なし'}</div>
        </div>
      </div>
    `;

    detailsArea.classList.remove('hidden');

    // 検証結果を表示
    showValidationResults(model);
  }

  // 検証結果を表示
  function showValidationResults(model) {
    const validationResults = container.querySelector('#validation-results');

    const accuracy = model.予測精度 || 0;
    const status = model.予測ステータス;

    let statusColor = 'var(--text-muted)';
    let statusText = '未検証';

    if (status === '完了' && accuracy >= 80) {
      statusColor = '#22c55e';
      statusText = '検証完了（適用可能）';
    } else if (status === '完了' && accuracy >= 60) {
      statusColor = '#f59e0b';
      statusText = '検証完了（要注意）';
    } else if (status === '完了') {
      statusColor = '#ef4444';
      statusText = '検証完了（精度不足）';
    }

    validationResults.innerHTML = `
      <div style="margin-bottom: 12px;">
        <div style="color: ${statusColor}; font-weight: 500; margin-bottom: 8px;">● ${statusText}</div>
        <div style="margin-bottom: 8px;">予測精度: ${accuracy}%</div>
        <div style="margin-bottom: 8px;">検証ステータス: ${status}</div>
        ${accuracy < 60 ? '<div style="color: #ef4444; font-size: 13px;">⚠ 予測精度が低いため、適用には注意が必要です</div>' : ''}
      </div>
    `;
  }

  // 影響範囲を更新
  function updateImpactScope() {
    const impactScope = container.querySelector('#impact-scope');
    const storeCount = selectedStores.size;

    if (storeCount === 0) {
      impactScope.innerHTML = '店舗を選択すると影響範囲が表示されます';
      return;
    }

    // 予想処理時間を計算（店舗数 × 2分）
    const estimatedTime = storeCount * 2;

    impactScope.innerHTML = `
      <div style="margin-bottom: 8px;"><strong>対象店舗数:</strong> ${storeCount}店舗</div>
      <div style="margin-bottom: 8px;"><strong>影響商品カテゴリ:</strong> 全カテゴリ</div>
      <div style="margin-bottom: 8px;"><strong>予想処理時間:</strong> 約${estimatedTime}分</div>
      ${storeCount >= 10 ? '<div style="color: #f59e0b; font-size: 13px;">⚠ 大規模な適用処理となります。処理時間にご注意ください。</div>' : ''}
    `;
  }

  // ログを追加
  function addLog(message, type = 'info') {
    const logArea = container.querySelector('#result-log');
    const timestamp = new Date().toLocaleTimeString();
    const colors = {
      info: 'var(--text-muted)',
      success: '#22c55e',
      warning: '#f59e0b',
      error: '#ef4444'
    };

    logArea.innerHTML += `<div style="color: ${colors[type]};">[${timestamp}] ${message}</div>`;
    logArea.scrollTop = logArea.scrollHeight;
  }

  // 適用処理を実行
  async function executeApply() {
    const modelId = container.querySelector('#model-select').value;
    const startDateTime = container.querySelector('#start-datetime').value;
    const backupEnabled = container.querySelector('#backup-enabled').checked;
    const retentionDays = parseInt(container.querySelector('#retention-days').value);

    // バリデーション
    if (!modelId) {
      alert('適用対象のモデルが選択されていません');
      return;
    }

    if (selectedStores.size === 0) {
      alert('適用対象の店舗が選択されていません');
      return;
    }

    if (!startDateTime) {
      alert('適用開始日時を設定してください');
      return;
    }

    const startDate = new Date(startDateTime);
    const now = new Date();
    if (startDate < now) {
      alert('適用開始日時は現在日時以降を指定してください');
      return;
    }

    if (retentionDays <= 0) {
      alert('現行モデル保持期間は1日以上を設定してください');
      return;
    }

    // 適用処理中チェック
    if (currentApplyProcess) {
      alert('既に適用処理が実行中です。処理完了後に再度実行してください。');
      return;
    }

    if (!confirm(`${selectedStores.size}店舗に対してモデルを適用します。実行しますか？`)) {
      return;
    }

    // 処理開始
    currentApplyProcess = true;
    container.querySelector('#btn-apply').disabled = true;
    container.querySelector('#progress-area').classList.remove('hidden');

    addLog('モデル適用処理を開始します', 'info');

    try {
      // 進捗更新
      let progress = 0;
      const progressBar = container.querySelector('#progress-bar');
      const progressText = container.querySelector('#progress-text');

      // バックアップ作成
      if (backupEnabled) {
        addLog('現行モデルのバックアップを作成中...', 'info');
        progressText.textContent = 'バックアップ作成中...';
        await new Promise(resolve => setTimeout(resolve, 2000));
        progress = 20;
        progressBar.style.width = progress + '%';
        addLog('バックアップ作成完了', 'success');
      }

      // 店舗ごとに適用
      const storeArray = Array.from(selectedStores);
      for (let i = 0; i < storeArray.length; i++) {
        const storeId = storeArray[i];
        addLog(`店舗 ${storeId} にモデルを適用中...`, 'info');
        progressText.textContent = `店舗適用中... (${i + 1}/${storeArray.length})`;

        // 実際の適用処理（シミュレーション）
        await new Promise(resolve => setTimeout(resolve, 1000));

        progress = 20 + (70 * (i + 1) / storeArray.length);
        progressBar.style.width = progress + '%';

        addLog(`店舗 ${storeId} への適用完了`, 'success');
      }

      // 最終確認
      addLog('適用後検証を実行中...', 'info');
      progressText.textContent = '適用後検証中...';
      await new Promise(resolve => setTimeout(resolve, 2000));

      progress = 100;
      progressBar.style.width = progress + '%';
      progressText.textContent = '適用完了';

      addLog('モデル適用処理が正常に完了しました', 'success');

      // ロールバックボタンを有効化
      container.querySelector('#btn-rollback').disabled = false;

    } catch (error) {
      addLog(`適用処理でエラーが発生しました: ${error.message}`, 'error');
    } finally {
      currentApplyProcess = null;
      container.querySelector('#btn-apply').disabled = false;
    }
  }

  // ロールバック処理
  async function executeRollback() {
    if (!container.querySelector('#btn-rollback').disabled) {
      if (!confirm('モデルをロールバックします。実行しますか？')) {
        return;
      }

      addLog('ロールバック処理を開始します', 'info');

      try {
        // ロールバック処理（シミュレーション）
        await new Promise(resolve => setTimeout(resolve, 3000));
        addLog('ロールバック処理が完了しました', 'success');
        container.querySelector('#btn-rollback').disabled = true;
      } catch (error) {
        addLog(`ロールバック処理でエラーが発生しました: ${error.message}`, 'error');
      }
    } else {
      alert('適用前のため、ロールバックできません');
    }
  }

  // イベントリスナー設定
  container.querySelector('#model-select').addEventListener('change', (e) => {
    if (e.target.value) {
      showModelDetails(e.target.value);
    } else {
      container.querySelector('#model-details').classList.add('hidden');
      container.querySelector('#validation-results').innerHTML = 'モデルを選択すると検証結果が表示されます';
    }
  });

  container.querySelector('#select-all-stores').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.store-checkbox');
    checkboxes.forEach(cb => {
      cb.checked = e.target.checked;
      if (e.target.checked) {
        selectedStores.add(cb.value);
      } else {
        selectedStores.delete(cb.value);
      }
    });
    updateImpactScope();
  });

  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('store-checkbox')) {
      if (e.target.checked) {
        selectedStores.add(e.target.value);
      } else {
        selectedStores.delete(e.target.value);
      }
      updateImpactScope();

      // 全選択チェックボックスの状態を更新
      const allCheckboxes = container.querySelectorAll('.store-checkbox');
      const checkedCount = container.querySelectorAll('.store-checkbox:checked').length;
      const selectAllCheckbox = container.querySelector('#select-all-stores');
      selectAllCheckbox.checked = checkedCount === allCheckboxes.length;
      selectAllCheckbox.indeterminate = checkedCount > 0 && checkedCount < allCheckboxes.length;
    }
  });

  container.querySelector('#retention-days').addEventListener('input', (e) => {
    const value = parseInt(e.target.value);
    if (value === 0) {
      alert('保持期間に0日が設定されています。1日以上を設定してください。');
    }
  });

  container.querySelector('#btn-apply').addEventListener('click', executeApply);
  container.querySelector('#btn-rollback').addEventListener('click', executeRollback);

  // 初期データ読み込み
  loadModels();
  loadStores();

  // 初期ログ
  addLog('モデル本番適用処理画面を初期化しました', 'info');
}
